def matches_filters(
    entry: AuditEntry,
    run_id: RunID | None,
    layer: AuditLayer | None,
    table_name: str | None,
    start_time: datetime | None,
    end_time: datetime | None,
) -> bool:
    """Return ``True`` when entry satisfies all optional filters."""
    if run_id is not None and entry.run_id != run_id:
        return False
    if layer is not None and entry.layer != layer:
        return False
    if table_name is not None and entry.table_name != table_name:
        return False
    if start_time is not None and entry.timestamp < start_time:
        return False
    return not (end_time is not None and entry.timestamp > end_time)

def process_audit_line(
    line: str,
    run_id: RunID | None,
    layer: AuditLayer | None,
    table_name: str | None,
    start_time: datetime | None,
    end_time: datetime | None,
) -> AuditEntry | None:
    """Parse single JSONL line and return matching entry when possible."""
    if not line.strip():
        return None

    try:
        data = deserialize_from_json(line)
        if not isinstance(data, dict):
            return None
        entry = parse_entry(data)
        return (
            entry
            if matches_filters(entry, run_id, layer, table_name, start_time, end_time)
            else None
        )
    except (ValueError, KeyError):
        return None

def _coerce_text(value: object, *, fallback: str) -> str:
    text = str(value).strip() if value is not None else ""
    return text or fallback

def _default_severity(event_data: JsonDict) -> str:
    severity = event_data.get("severity")
    if severity is not None:
        return _coerce_text(severity, fallback="info")
    status = _coerce_text(event_data.get("status"), fallback="")
    if status in {"failed", "failure", "error"}:
        return "error"
    if status in {"warning", "degraded"}:
        return "warning"
    return "info"

def _read_json_object_or_empty(path: Path) -> dict[str, object]:
    """Best-effort JSON object read for planner metadata."""
    if path.suffix not in {".json", ".jsonl"}:
        return {}
    try:
        if path.suffix == ".jsonl":
            line = next(
                (
                    item
                    for item in path.read_text(encoding="utf-8").splitlines()
                    if item
                ),
                "",
            )
            if not line:
                return {}
            payload = json.loads(line)
        else:
            payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, StopIteration, json.JSONDecodeError):
        return {}
    if not isinstance(payload, dict):
        return {}
    return {str(key): value for key, value in payload.items()}

def _is_payload_stale(path: Path, payload: dict[str, object], cutoff: datetime) -> bool:
    created_at = _resolve_payload_or_file_time(path, payload)
    return created_at is not None and created_at < cutoff

def _resolve_payload_or_file_time(
    path: Path,
    payload: dict[str, object],
) -> datetime | None:
    for key in ("created_at", "updated_at", "occurred_at"):
        timestamp = _parse_datetime(_payload_value(payload, key))
        if timestamp is not None:
            return timestamp
    try:
        return datetime.fromtimestamp(path.stat().st_mtime, tz=UTC)
    except OSError:
        return None

def _parse_datetime(value: object) -> datetime | None:
    if value is None:
        return None
    try:
        timestamp = datetime.fromisoformat(str(value))
    except ValueError:
        return None
    if timestamp.tzinfo is None:
        return timestamp.replace(tzinfo=UTC)
    return timestamp.astimezone(UTC)

def _artifact_id(
    *,
    surface: ControlPlaneArtifactSurface,
    path: Path,
    payload: dict[str, object],
) -> str:
    if surface is ControlPlaneArtifactSurface.RUN_MANIFEST:
        return str(payload.get("manifest_id") or path.stem)
    if surface is ControlPlaneArtifactSurface.RUN_LEDGER:
        return str(payload.get("manifest_id") or path.stem)
    if surface is ControlPlaneArtifactSurface.EFFECTIVE_CONFIG:
        return str(payload.get("artifact_id") or path.stem)
    if surface is ControlPlaneArtifactSurface.LINEAGE:
        return str(
            payload.get("stored_fragment_id") or payload.get("fragment_id") or path.stem
        )
    if surface is ControlPlaneArtifactSurface.CHECKPOINT:
        return (
            _payload_text(payload, "manifest_id")
            or _payload_text(payload, "run_id")
            or path.stem
        )
    if surface is ControlPlaneArtifactSurface.CACHED_BRONZE:
        return _content_addressed_file_snapshot_id(path)
    return path.stem

def _effective_config_artifact_id(payload: dict[str, object]) -> str | None:
    code_provenance = payload.get("code_provenance")
    if not isinstance(code_provenance, dict):
        return None
    return _optional_text(code_provenance.get("effective_config_artifact_id"))

def _input_snapshot_ids(payload: dict[str, object]) -> tuple[str, ...]:
    source_refs = payload.get("source_refs")
    if not isinstance(source_refs, list):
        return ()
    snapshot_ids: list[str] = []
    for source_ref in source_refs:
        if not isinstance(source_ref, dict):
            continue
        input_snapshots = source_ref.get("input_snapshots")
        if not isinstance(input_snapshots, list):
            continue
        for input_snapshot in input_snapshots:
            if not isinstance(input_snapshot, dict):
                continue
            snapshot_id = _optional_text(input_snapshot.get("snapshot_id"))
            if snapshot_id is not None:
                snapshot_ids.append(snapshot_id)
    return tuple(snapshot_ids)

def _payload_value(payload: dict[str, object], key: str) -> object:
    if key in payload:
        return payload.get(key)
    metadata = payload.get("metadata")
    if isinstance(metadata, dict) and key in metadata:
        return metadata.get(key)
    return None

def _content_addressed_file_snapshot_id(path: Path) -> str:
    digest = hashlib.sha256()
    try:
        with path.open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
    except OSError:
        return f"unreadable:{path.stem}"
    return f"sha256:{digest.hexdigest()}"

def _indexed_stem(path: Path) -> str | None:
    if path.parent.name not in {
        "_by_fragment_id",
        "_by_manifest_id",
        "_by_node_id",
        "_by_run_id",
        "_occurrences",
    }:
        return None
    return path.stem

def _lineage_fragment_id_candidates(payload: dict[str, object]) -> tuple[str, ...]:
    candidates = (
        _optional_text(payload.get("stored_fragment_id")),
        _optional_text(payload.get("fragment_id")),
    )
    return tuple(candidate for candidate in candidates if candidate)

def _manifest_or_run_is_protected(
    payload: dict[str, object],
    *,
    manifest_ids: frozenset[str],
    run_ids: frozenset[str],
) -> bool:
    manifest_id = _optional_text(payload.get("manifest_id"))
    run_id = _optional_text(payload.get("run_id"))
    return (manifest_id in manifest_ids) or (run_id in run_ids)

def _optional_text(value: object) -> str | None:
    if value is None:
        return None
    text = str(value).strip()
    return text or None

def _resolve_lifecycle_reason(*, stale: bool, protected_by: tuple[str, ...]) -> str:
    if any(reason.startswith("evidence_floor:") for reason in protected_by):
        return "reproducibility_evidence_floor"
    if protected_by:
        return "protected_reference"
    if stale:
        return "retention_expired"
    return "within_retention_window"

"""Planning helpers for file-backed control-plane artifact lifecycle."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime
from pathlib import Path

from bioetl.domain.control_plane import (
    ControlPlaneArtifactLifecycleDecision,
    ControlPlaneArtifactLifecyclePolicy,
    ControlPlaneArtifactRef,
    ControlPlaneArtifactReplayImpact,
    ControlPlaneArtifactSurface,
)
from bioetl.domain.control_plane.reproducibility_policy import (
    STRICT_PERSISTENCE_PROFILES,
)
from bioetl.domain.control_plane.reproducibility_profiles import (
    resolve_reproducibility_family_profile,
)
from bioetl.infrastructure.control_plane.file_artifact_lifecycle_payloads import (
    _artifact_id,
    _effective_config_artifact_id,
    _input_snapshot_ids,
    _is_payload_stale,
    _lineage_fragment_id_candidates,
    _manifest_or_run_is_protected,
    _optional_text,
    _payload_text,
    _read_json_object_or_empty,
    _resolve_lifecycle_reason,
    _resolve_payload_or_file_time,
)
from bioetl.infrastructure.control_plane.file_artifact_lifecycle_reasons import (
    _protected_by,
)
from bioetl.infrastructure.control_plane.file_artifact_lifecycle_types import (
    _ProtectedRefs,
)

__all__ = ["_ProtectedRefs", "_iter_artifact_refs", "_resolve_protected_refs"]

_INDEX_DIR_NAMES = {
    "_by_fragment_id",
    "_by_manifest_id",
    "_by_node_id",
    "_by_run_id",
    "_occurrences",
}
_EVIDENCE_FLOOR_PROFILES = STRICT_PERSISTENCE_PROFILES


@dataclass(slots=True)

def _collect_manifest_protections(
    *,
    base_path: Path,
    cutoff: datetime,
    refs: _ProtectedRefAccumulator,
    allow_profile_floor_violation: bool,
) -> None:
    for manifest_path in _iter_surface_files(
        base_path, ControlPlaneArtifactSurface.RUN_MANIFEST
    ):
        if manifest_path.parent.name in _INDEX_DIR_NAMES:
            continue
        payload = _read_json_object_or_empty(manifest_path)
        if not payload:
            continue
        is_stale = _is_payload_stale(manifest_path, payload, cutoff)
        if not is_stale:
            _record_manifest_protections(
                path=manifest_path,
                payload=payload,
                refs=refs,
                evidence_floor=False,
            )
            continue
        if allow_profile_floor_violation or not _requires_evidence_floor(payload):
            continue
        _record_manifest_protections(
            path=manifest_path,
            payload=payload,
            refs=refs,
            evidence_floor=True,
        )

def _record_manifest_protections(
    *,
    path: Path,
    payload: dict[str, object],
    refs: _ProtectedRefAccumulator,
    evidence_floor: bool,
) -> None:
    manifest_id = str(payload.get("manifest_id") or path.stem)
    refs.manifest_ids.add(manifest_id)
    if evidence_floor:
        refs.evidence_floor_manifest_ids.add(manifest_id)
    run_id = _optional_text(payload.get("run_id"))
    if run_id is not None:
        refs.run_ids.add(run_id)
        if evidence_floor:
            refs.evidence_floor_run_ids.add(run_id)
    replay_manifest_id = _optional_text(payload.get("replay_of_manifest_id"))
    if replay_manifest_id is not None:
        refs.manifest_ids.add(replay_manifest_id)
    artifact_id = _effective_config_artifact_id(payload)
    if artifact_id is not None:
        refs.effective_config_artifact_ids.add(artifact_id)
        if evidence_floor:
            refs.evidence_floor_effective_config_artifact_ids.add(artifact_id)
    snapshot_ids = _input_snapshot_ids(payload)
    refs.input_snapshot_ids.update(snapshot_ids)
    if evidence_floor:
        refs.evidence_floor_input_snapshot_ids.update(snapshot_ids)

def _requires_evidence_floor(payload: dict[str, object]) -> bool:
    """Return whether one stale manifest declares a replay/forensic floor."""
    profile = _required_persistence_profile(payload)
    return profile in _EVIDENCE_FLOOR_PROFILES or _supports_historical_replay_floor(
        payload
    )

def _required_persistence_profile(payload: dict[str, object]) -> str:
    launch_context = payload.get("launch_context")
    if isinstance(launch_context, dict):
        profile = _optional_text(launch_context.get("required_persistence_profile"))
        if profile is not None:
            return profile
    return _optional_text(payload.get("required_persistence_profile")) or ""

def _supports_historical_replay_floor(payload: dict[str, object]) -> bool:
    """Protect retained replay-supported families from aging into uncertifiable runs."""
    provider = _optional_text(payload.get("provider"))
    entity = _optional_text(payload.get("entity"))
    if provider is None or entity is None:
        return False
    contract_ref = _payload_contract_ref(payload) or f"{provider}.{entity}"
    try:
        profile = resolve_reproducibility_family_profile(
            provider=provider,
            entity=entity,
            contract_ref=contract_ref,
            execution_context=_payload_execution_context(payload),
        )
    except ValueError:
        return False
    return (
        profile.broader_historical_exact_replay_policy
        == "certified_historical_exact_replay_tranche_supported"
    )

def _payload_contract_ref(payload: dict[str, object]) -> str | None:
    provenance = payload.get("code_provenance")
    if not isinstance(provenance, dict):
        return None
    return _optional_text(provenance.get("contract_ref"))

def _payload_execution_context(
    payload: dict[str, object],
) -> str:
    launch_context = payload.get("launch_context")
    if isinstance(launch_context, dict):
        execution_context = _optional_text(launch_context.get("execution_context"))
        if execution_context is not None:
            return execution_context
    if _optional_text(payload.get("provider")) == "composite":
        return "composite"
    return "source"

def _collect_checkpoint_protections(
    *,
    base_path: Path,
    cutoff: datetime,
    refs: _ProtectedRefAccumulator,
) -> None:
    for checkpoint_path in _iter_surface_files(
        base_path, ControlPlaneArtifactSurface.CHECKPOINT
    ):
        payload = _read_json_object_or_empty(checkpoint_path)
        if not payload or _is_payload_stale(checkpoint_path, payload, cutoff):
            continue
        _record_checkpoint_protections(payload=payload, refs=refs)

def _record_checkpoint_protections(
    *,
    payload: dict[str, object],
    refs: _ProtectedRefAccumulator,
) -> None:
    run_id = _payload_text(payload, "run_id")
    if run_id is not None:
        refs.run_ids.add(run_id)
    manifest_id = _payload_text(payload, "manifest_id")
    if manifest_id is not None:
        refs.manifest_ids.add(manifest_id)
    artifact_id = _payload_text(payload, "effective_config_artifact_id")
    if artifact_id is not None:
        refs.effective_config_artifact_ids.add(artifact_id)

def _collect_lineage_protections(
    *,
    base_path: Path,
    refs: _ProtectedRefAccumulator,
) -> None:
    manifest_ids = frozenset(refs.manifest_ids)
    run_ids = frozenset(refs.run_ids)
    evidence_floor_manifest_ids = frozenset(refs.evidence_floor_manifest_ids)
    evidence_floor_run_ids = frozenset(refs.evidence_floor_run_ids)
    for fragment_path in _lineage_fragment_files(base_path):
        payload = _read_json_object_or_empty(fragment_path)
        if not payload:
            continue
        if _manifest_or_run_is_protected(
            payload,
            manifest_ids=manifest_ids,
            run_ids=run_ids,
        ):
            refs.lineage_fragment_ids.update(_lineage_fragment_id_candidates(payload))
        if _manifest_or_run_is_protected(
            payload,
            manifest_ids=evidence_floor_manifest_ids,
            run_ids=evidence_floor_run_ids,
        ):
            refs.evidence_floor_lineage_fragment_ids.update(
                _lineage_fragment_id_candidates(payload)
            )

def _iter_artifact_refs(
    *,
    base_path: Path,
    cutoff: datetime,
    protected_refs: _ProtectedRefs,
) -> tuple[ControlPlaneArtifactRef, ...]:
    refs: list[ControlPlaneArtifactRef] = []
    for surface in ControlPlaneArtifactSurface:
        for path in _iter_surface_files(base_path, surface):
            refs.append(
                _build_artifact_ref(
                    surface=surface,
                    path=path,
                    cutoff=cutoff,
                    protected_refs=protected_refs,
                )
            )
    return tuple(refs)

def _iter_surface_files(
    base_path: Path,
    surface: ControlPlaneArtifactSurface,
) -> tuple[Path, ...]:
    surface_root = _surface_root(base_path, surface)
    if not surface_root.exists():
        return ()
    return tuple(path for path in surface_root.rglob("*") if path.is_file())

def _surface_root(base_path: Path, surface: ControlPlaneArtifactSurface) -> Path:
    if surface in {
        ControlPlaneArtifactSurface.CACHED_BRONZE,
        ControlPlaneArtifactSurface.CHECKPOINT,
    }:
        return base_path.parent / surface.value
    return base_path / surface.value

def _lineage_fragment_files(base_path: Path) -> tuple[Path, ...]:
    fragments_root = base_path / ControlPlaneArtifactSurface.LINEAGE / "fragments"
    if not fragments_root.exists():
        return ()
    return tuple(path for path in fragments_root.glob("*.json") if path.is_file())

def _protected_by(
    *,
    surface: ControlPlaneArtifactSurface,
    path: Path,
    payload: dict[str, object],
    protected_refs: _ProtectedRefs,
) -> tuple[str, ...]:
    if surface in {
        ControlPlaneArtifactSurface.RUN_MANIFEST,
        ControlPlaneArtifactSurface.RUN_LEDGER,
    }:
        reasons = _manifest_or_ledger_protected_reasons(
            path=path,
            payload=payload,
            protected_refs=protected_refs,
        )
        return _dedupe_reasons(reasons)
    if surface is ControlPlaneArtifactSurface.EFFECTIVE_CONFIG:
        reasons = _effective_config_protected_reasons(
            path=path,
            payload=payload,
            protected_refs=protected_refs,
        )
        return _dedupe_reasons(reasons)
    if surface is ControlPlaneArtifactSurface.LINEAGE:
        reasons = _lineage_protected_reasons(
            path=path,
            payload=payload,
            protected_refs=protected_refs,
        )
        return _dedupe_reasons(reasons)
    if surface is ControlPlaneArtifactSurface.CHECKPOINT:
        reasons = _checkpoint_protected_reasons(
            payload=payload,
            protected_refs=protected_refs,
        )
        return _dedupe_reasons(reasons)
    if surface is ControlPlaneArtifactSurface.CACHED_BRONZE:
        reasons = _cached_bronze_protected_reasons(
            path=path,
            protected_refs=protected_refs,
        )
        return _dedupe_reasons(reasons)
    return ()

def _manifest_or_ledger_protected_reasons(
    *,
    path: Path,
    payload: dict[str, object],
    protected_refs: _ProtectedRefs,
) -> list[str]:
    reasons: list[str] = []
    manifest_id = str(payload.get("manifest_id") or path.stem)
    run_id = _optional_text(payload.get("run_id"))
    if manifest_id in protected_refs.manifest_ids:
        reasons.append(f"manifest:{manifest_id}")
    if manifest_id in protected_refs.evidence_floor_manifest_ids:
        reasons.append(f"evidence_floor:manifest:{manifest_id}")
    if run_id in protected_refs.run_ids:
        reasons.append(f"run:{run_id}")
    if run_id in protected_refs.evidence_floor_run_ids:
        reasons.append(f"evidence_floor:run:{run_id}")
    indexed_run_id = _indexed_stem(path)
    if indexed_run_id in protected_refs.run_ids:
        reasons.append(f"run:{indexed_run_id}")
    if indexed_run_id in protected_refs.evidence_floor_run_ids:
        reasons.append(f"evidence_floor:run:{indexed_run_id}")
    return reasons

def _effective_config_protected_reasons(
    *,
    path: Path,
    payload: dict[str, object],
    protected_refs: _ProtectedRefs,
) -> list[str]:
    reasons: list[str] = []
    artifact_id = str(payload.get("artifact_id") or path.stem)
    run_id = _optional_text(payload.get("run_id")) or _indexed_stem(path)
    if artifact_id in protected_refs.effective_config_artifact_ids:
        reasons.append(f"effective_config:{artifact_id}")
    if artifact_id in protected_refs.evidence_floor_effective_config_artifact_ids:
        reasons.append(f"evidence_floor:effective_config:{artifact_id}")
    if run_id in protected_refs.run_ids:
        reasons.append(f"run:{run_id}")
    if run_id in protected_refs.evidence_floor_run_ids:
        reasons.append(f"evidence_floor:run:{run_id}")
    return reasons

def _lineage_protected_reasons(
    *,
    path: Path,
    payload: dict[str, object],
    protected_refs: _ProtectedRefs,
) -> list[str]:
    reasons: list[str] = []
    for fragment_id in _lineage_fragment_id_candidates(payload) or (path.stem,):
        if fragment_id in protected_refs.lineage_fragment_ids:
            reasons.append(f"lineage:{fragment_id}")
        if fragment_id in protected_refs.evidence_floor_lineage_fragment_ids:
            reasons.append(f"evidence_floor:lineage:{fragment_id}")
    if not _manifest_or_run_is_protected(
        payload,
        manifest_ids=protected_refs.manifest_ids,
        run_ids=protected_refs.run_ids,
    ):
        return reasons
    manifest_id = _optional_text(payload.get("manifest_id"))
    run_id = _optional_text(payload.get("run_id"))
    if manifest_id is not None:
        reasons.append(f"manifest:{manifest_id}")
        if manifest_id in protected_refs.evidence_floor_manifest_ids:
            reasons.append(f"evidence_floor:manifest:{manifest_id}")
    if run_id is not None:
        reasons.append(f"run:{run_id}")
        if run_id in protected_refs.evidence_floor_run_ids:
            reasons.append(f"evidence_floor:run:{run_id}")
    return reasons

def _checkpoint_protected_reasons(
    *,
    payload: dict[str, object],
    protected_refs: _ProtectedRefs,
) -> list[str]:
    reasons: list[str] = []
    run_id = _payload_text(payload, "run_id")
    manifest_id = _payload_text(payload, "manifest_id")
    artifact_id = _payload_text(payload, "effective_config_artifact_id")
    if run_id in protected_refs.run_ids:
        reasons.append(f"run:{run_id}")
    if run_id in protected_refs.evidence_floor_run_ids:
        reasons.append(f"evidence_floor:run:{run_id}")
    if manifest_id in protected_refs.manifest_ids:
        reasons.append(f"manifest:{manifest_id}")
    if manifest_id in protected_refs.evidence_floor_manifest_ids:
        reasons.append(f"evidence_floor:manifest:{manifest_id}")
    if artifact_id in protected_refs.effective_config_artifact_ids:
        reasons.append(f"effective_config:{artifact_id}")
    if artifact_id in protected_refs.evidence_floor_effective_config_artifact_ids:
        reasons.append(f"evidence_floor:effective_config:{artifact_id}")
    return reasons

def _cached_bronze_protected_reasons(
    *,
    path: Path,
    protected_refs: _ProtectedRefs,
) -> list[str]:
    snapshot_id = _content_addressed_file_snapshot_id(path)
    if snapshot_id in protected_refs.evidence_floor_input_snapshot_ids:
        return [f"snapshot:{snapshot_id}", f"evidence_floor:snapshot:{snapshot_id}"]
    if snapshot_id in protected_refs.input_snapshot_ids:
        return [f"snapshot:{snapshot_id}"]
    return []

"""File-backed lifecycle planner for control-plane artifacts."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import timedelta
from pathlib import Path
from typing import TYPE_CHECKING

from bioetl.domain.control_plane import (
    ControlPlaneArtifactLifecycleApplyResult,
    ControlPlaneArtifactLifecyclePlan,
    ControlPlaneArtifactLifecyclePolicy,
    ControlPlaneArtifactRef,
)
from bioetl.infrastructure.control_plane.file_artifact_lifecycle_planning import (
    _iter_artifact_refs,
    _resolve_protected_refs,
)

if TYPE_CHECKING:
    from bioetl.domain.ports import LoggerPort, MetricsPort

__all__ = ["FileControlPlaneArtifactLifecycleStore"]


@dataclass(slots=True)

def _missing_source_issue(
    contract_ref: str,
    source_path: str,
) -> RegistryValidationIssue:
    return RegistryValidationIssue(
        message=f"Source file not found: {source_path}",
        severity=RegistryValidationSeverity.BLOCKING,
        contract_ref=contract_ref,
        field="source_path",
    )

def _missing_artifact_issue(
    contract_ref: str,
    artifact_path: str,
) -> RegistryValidationIssue:
    return RegistryValidationIssue(
        message=f"Published artifact not found: {artifact_path}",
        severity=RegistryValidationSeverity.BLOCKING,
        contract_ref=contract_ref,
        field="published_artifacts",
    )

class FileContractRegistryStore:
    """Persist contract registries as YAML files and validate file references."""

    registry_path: Path

    def load(self, registry_path: Path | None = None) -> ContractRegistry:
        """Load one registry from YAML storage."""
        path = registry_path or self.registry_path
        data = self._read_registry_data(path)
        return ContractRegistry.from_dict(data)

    def save(
        self,
        registry: ContractRegistry,
        output_path: Path | None = None,
    ) -> None:
        """Serialize one registry to YAML storage."""
        target_path = output_path or self.registry_path
        serialized = yaml.safe_dump(registry.to_dict(), sort_keys=False)
        try:
            target_path.parent.mkdir(parents=True, exist_ok=True)
            atomic_write_text(target_path, serialized)
        except OSError as exc:
            raise RegistryLoadError(f"Failed to save registry: {exc!s}") from exc

    def validate_filesystem_consistency(
        self,
        registry: ContractRegistry,
        base_path: Path | None = None,
    ) -> RegistryValidationResult:
        """Validate that source and artifact references exist on filesystem."""
        resolved_base_path = base_path or self.registry_path.parent
        issues: list[RegistryValidationIssue] = []
        for contract_ref, entry in registry.entries.items():
            if not resolve_path(entry.source_path, resolved_base_path).exists():
                issues.append(_missing_source_issue(contract_ref, entry.source_path))
            for artifact_path in entry.published_artifacts:
                if resolve_path(artifact_path, resolved_base_path).exists():
                    continue
                issues.append(_missing_artifact_issue(contract_ref, artifact_path))
        return RegistryValidationResult(valid=len(issues) == 0, issues=issues)

    @staticmethod
    def _read_registry_data(path: Path) -> JsonDict:
        try:
            content = path.read_text(encoding="utf-8")
        except OSError as exc:
            raise RegistryLoadError(f"Failed to read registry: {exc!s}") from exc
        try:
            loaded = yaml.safe_load(content)
        except yaml.YAMLError as exc:
            raise RegistryLoadError(f"Invalid registry YAML: {exc!s}") from exc
        if not isinstance(loaded, dict):
            raise RegistryLoadError("Invalid registry format: expected mapping")
        return loaded

def create_contract_registry(registry_path: Path) -> ContractRegistry:
    """Compatibility helper for loading a file-backed contract registry."""
    return FileContractRegistryStore(registry_path).load()

class FileEffectiveConfigArtifactStore:
    """Persist effective-config artifacts as JSON files under control-plane."""

    base_path: Path

    def save(
        self, *, artifact_id: str, run_id: RunID, payload: dict[str, object]
    ) -> None:
        """Persist immutable semantic payload and maintain occurrence indexes."""
        artifact_path = self.base_path / f"{artifact_id}.json"
        occurrence_dir = self.base_path / _OCCURRENCE_DIR
        occurrence_path = occurrence_dir / f"{run_id}.json"
        run_index_dir = self.base_path / _RUN_INDEX_DIR
        run_index_path = run_index_dir / f"{run_id}.txt"
        artifact_created = False
        occurrence_created = False

        self.base_path.mkdir(parents=True, exist_ok=True)
        occurrence_dir.mkdir(parents=True, exist_ok=True)
        run_index_dir.mkdir(parents=True, exist_ok=True)
        try:
            artifact_created = self._save_semantic_artifact(
                artifact_path=artifact_path,
                artifact_id=artifact_id,
                payload=payload,
            )
            atomic_write_text(
                occurrence_path,
                _to_stable_json(
                    _build_occurrence_payload(
                        artifact_id=artifact_id,
                        run_id=run_id,
                        payload=payload,
                    )
                ),
            )
            occurrence_created = True
            atomic_write_text(run_index_path, artifact_id)
        except (AtomicWriteError, OSError, TypeError, ValueError):
            if occurrence_created:
                self._rollback_file(occurrence_path)
            if artifact_created:
                self._rollback_artifact_file(artifact_path)
            raise

    def get(self, artifact_id: str) -> dict[str, object] | None:
        """Load one artifact payload by identifier."""
        artifact_path = self.base_path / f"{artifact_id}.json"
        if not artifact_path.exists():
            return None
        return _read_json_object(artifact_path)

    def get_by_run_id(self, run_id: RunID) -> dict[str, object] | None:
        """Resolve run-id index to artifact identifier and load payload."""
        run_index_path = self.base_path / _RUN_INDEX_DIR / f"{run_id}.txt"
        if not run_index_path.exists():
            return None
        artifact_id = run_index_path.read_text(encoding="utf-8").strip()
        if not artifact_id:
            return None
        return self.get(artifact_id)

    def get_occurrence_by_run_id(self, run_id: RunID) -> dict[str, object] | None:
        """Load occurrence metadata for one run identifier."""
        occurrence_path = self.base_path / _OCCURRENCE_DIR / f"{run_id}.json"
        if not occurrence_path.exists():
            return None
        return _read_json_object(occurrence_path)

    def diff_occurrences_by_run_id(
        self,
        left_run_id: RunID,
        right_run_id: RunID,
    ) -> dict[str, object]:
        """Compare semantic and occurrence identity for two effective configs."""
        left_artifact = self.get_by_run_id(left_run_id)
        right_artifact = self.get_by_run_id(right_run_id)
        left_occurrence = self.get_occurrence_by_run_id(left_run_id)
        right_occurrence = self.get_occurrence_by_run_id(right_run_id)
        semantic_equivalent = (
            left_artifact is not None
            and right_artifact is not None
            and _to_stable_json(left_artifact) == _to_stable_json(right_artifact)
        )
        occurrence_differences = _diff_occurrence_payloads(
            left_occurrence,
            right_occurrence,
        )
        return {
            "left_run_id": str(left_run_id),
            "right_run_id": str(right_run_id),
            "left_artifact_present": left_artifact is not None,
            "right_artifact_present": right_artifact is not None,
            "left_occurrence_present": left_occurrence is not None,
            "right_occurrence_present": right_occurrence is not None,
            "semantic_equivalent": semantic_equivalent,
            "occurrence_only": semantic_equivalent and bool(occurrence_differences),
            "differences": occurrence_differences,
        }

    def _save_semantic_artifact(
        self,
        *,
        artifact_path: Path,
        artifact_id: str,
        payload: dict[str, object],
    ) -> bool:
        """Write semantic artifact once and reject conflicting rewrites."""
        semantic_payload = _build_semantic_payload(
            artifact_id=artifact_id,
            payload=payload,
        )
        semantic_text = _to_stable_json(semantic_payload)
        if artifact_path.exists():
            existing_payload = _read_json_object(artifact_path)
            existing_semantic_payload = _build_semantic_payload(
                artifact_id=artifact_id,
                payload=existing_payload,
            )
            if _to_stable_json(existing_semantic_payload) == semantic_text:
                return False
            raise EffectiveConfigArtifactConflictError(
                "Effective-config semantic artifact already exists with "
                f"different content: {artifact_id}"
            )
        atomic_write_text(artifact_path, semantic_text)
        return True

    @staticmethod
    def _rollback_artifact_file(artifact_path: Path) -> None:
        """Remove a persisted artifact file when a later consistency step fails."""
        FileEffectiveConfigArtifactStore._rollback_file(artifact_path)

    @staticmethod
    def _rollback_file(path: Path) -> None:
        """Remove a file created during a failed multi-file write."""
        with suppress(OSError):
            if path.exists():
                path.unlink()

def _read_json_object(path: Path) -> dict[str, object]:
    payload = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(payload, dict):
        raise ValueError("Effective-config artifact payload must be a JSON object")
    return {str(key): value for key, value in payload.items()}

def _build_semantic_payload(
    *,
    artifact_id: str,
    payload: dict[str, object],
) -> dict[str, object]:
    """Return the immutable semantic record persisted by artifact id."""
    semantic_artifact = payload.get(_SEMANTIC_ARTIFACT_KEY)
    if not isinstance(semantic_artifact, dict):
        return {str(key): value for key, value in payload.items()}

    semantic_payload: dict[str, object] = {
        "artifact_id": payload.get("artifact_id", artifact_id),
        _SEMANTIC_ARTIFACT_KEY: semantic_artifact,
    }
    schema_version = payload.get("schema_version")
    if schema_version is None:
        schema_version = semantic_artifact.get("schema_version")
    if schema_version is not None:
        semantic_payload["schema_version"] = schema_version
    return semantic_payload

def _build_occurrence_payload(
    *,
    artifact_id: str,
    run_id: RunID,
    payload: dict[str, object],
) -> dict[str, object]:
    """Return the run-specific occurrence record persisted by run id."""
    occurrence_envelope = payload.get(_OCCURRENCE_ENVELOPE_KEY)
    if not isinstance(occurrence_envelope, dict):
        occurrence_envelope = {}
    occurrence_payload: dict[str, object] = {
        "artifact_id": artifact_id,
        "run_id": str(run_id),
        _OCCURRENCE_ENVELOPE_KEY: occurrence_envelope,
    }
    schema_version = payload.get("schema_version")
    if schema_version is not None:
        occurrence_payload["schema_version"] = schema_version
    return occurrence_payload

def _flatten_occurrence_payload(payload: dict[str, object] | None) -> dict[str, object]:
    """Flatten occurrence payload fields into stable diff paths."""
    if payload is None:
        return {}
    flattened = {
        key: value for key, value in payload.items() if key != _OCCURRENCE_ENVELOPE_KEY
    }
    occurrence_envelope = payload.get(_OCCURRENCE_ENVELOPE_KEY)
    if isinstance(occurrence_envelope, dict):
        for key, value in sorted(occurrence_envelope.items()):
            flattened[f"{_OCCURRENCE_ENVELOPE_KEY}.{key}"] = value
    return flattened

def _diff_occurrence_payloads(
    left: dict[str, object] | None,
    right: dict[str, object] | None,
) -> list[dict[str, object]]:
    """Return field-level occurrence differences for operator diagnostics."""
    left_flat = _flatten_occurrence_payload(left)
    right_flat = _flatten_occurrence_payload(right)
    differences: list[dict[str, object]] = []
    for field in sorted(set(left_flat) | set(right_flat)):
        left_value = left_flat.get(field)
        right_value = right_flat.get(field)
        if left_value == right_value:
            continue
        differences.append(
            {
                "field": field,
                "left": left_value,
                "right": right_value,
            }
        )
    return differences

class _HistoricalReplayClosureReportLike(Protocol):
    report_id: str

    def to_dict(self) -> dict[str, object]: ...

def _stable_key_filename(key: str) -> str:
    """Return a filesystem-safe filename stem for one semantic key."""
    return hashlib.sha256(key.encode("utf-8")).hexdigest()

def _build_stored_fragment_id(fragment: LineageGraphFragment) -> str:
    """Return one occurrence-scoped stored fragment identity."""
    anchors = [fragment.fragment_id]
    if fragment.run_id is not None:
        anchors.append(fragment.run_id)
    if fragment.manifest_id is not None:
        anchors.append(fragment.manifest_id)
    if len(anchors) == 1:
        return fragment.fragment_id
    digest = hashlib.sha256("|".join(anchors).encode("utf-8")).hexdigest()[:12]
    return f"{fragment.fragment_id}:occurrence:{digest}"

def _load_fragment_ids(index_path: Path, *, key: str) -> list[str]:
    """Load fragment identifiers from one JSONL index file."""
    if not index_path.exists():
        return []
    raw_text = index_path.read_text(encoding="utf-8")
    if not raw_text.strip():
        return []
    if not raw_text.endswith(("\n", "\r")):
        raise _LineageIndexCorruptionError(
            f"Lineage index '{index_path}' is corrupted: truncated tail line"
        )
    fragment_ids: dict[str, None] = {}
    for line_number, line in enumerate(raw_text.splitlines(), start=1):
        if not line.strip():
            continue
        try:
            payload = json.loads(line)
        except json.JSONDecodeError as error:
            raise _LineageIndexCorruptionError(
                f"Lineage index '{index_path}' is corrupted at line "
                f"{line_number}: {error.msg}"
            ) from error
        if not isinstance(payload, dict):
            raise _LineageIndexCorruptionError(
                f"Lineage index '{index_path}' is corrupted at line "
                f"{line_number}: payload must be a JSON object"
            )
        if str(payload.get("key")) != key:
            raise _LineageIndexCorruptionError(
                f"Lineage index '{index_path}' is corrupted at line "
                f"{line_number}: unexpected key"
            )
        fragment_id = payload.get("fragment_id")
        if fragment_id is None or not str(fragment_id).strip():
            raise _LineageIndexCorruptionError(
                f"Lineage index '{index_path}' is corrupted at line "
                f"{line_number}: missing fragment_id"
            )
        fragment_ids[str(fragment_id)] = None
    return list(fragment_ids)

def _truncate_index_to_offset(path: Path, *, offset: int) -> None:
    """Best-effort rollback of one lineage index file to a known-good offset."""
    if not path.exists():
        return
    file_descriptor = os.open(path, os.O_RDWR)
    try:
        os.ftruncate(file_descriptor, offset)
        os.fsync(file_descriptor)
    finally:
        os.close(file_descriptor)

def _append_jsonl_payload(path: Path, payload: bytes) -> int:
    """Append one full JSONL payload with rollback on partial writes."""
    path.parent.mkdir(parents=True, exist_ok=True)
    file_descriptor = os.open(path, _LINEAGE_APPEND_OPEN_FLAGS, 0o666)
    bytes_written = 0
    checkpoint_size = 0
    try:
        checkpoint_size = os.fstat(file_descriptor).st_size
        while bytes_written < len(payload):
            written = os.write(file_descriptor, payload[bytes_written:])
            if written <= 0:
                raise OSError("Lineage index append produced an empty write")
            bytes_written += written
        os.fsync(file_descriptor)
        return checkpoint_size
    except OSError:
        if bytes_written > 0:
            try:
                os.ftruncate(file_descriptor, checkpoint_size)
                os.fsync(file_descriptor)
            except OSError:
                pass
        raise
    finally:
        os.close(file_descriptor)

class FileLineageStore(LineageStorePort):
    """Persist lineage graph fragments under the control-plane output tree."""

    base_path: Path
    metrics: MetricsPort | None = None

    def save(self, fragment: LineageGraphFragment) -> None:
        """Persist one fragment JSON and maintain lightweight lookup indexes."""
        fragments_dir = self.base_path / "fragments"
        fragments_dir.mkdir(parents=True, exist_ok=True)
        stored_fragment_id = fragment.stored_fragment_id or _build_stored_fragment_id(
            fragment
        )
        persisted_fragment = replace(
            fragment,
            stored_fragment_id=stored_fragment_id,
        )
        fragment_path = self._fragment_path(stored_fragment_id)
        existing_fragment_payload = (
            fragment_path.read_text(encoding="utf-8")
            if fragment_path.exists()
            else None
        )
        index_rollbacks: list[tuple[Path, int]] = []
        try:
            atomic_write_text(
                fragment_path,
                json.dumps(persisted_fragment.to_dict(), indent=2, sort_keys=True),
            )
            index_rollbacks.append(
                self._append_index(
                    self._semantic_fragment_index_path(fragment.fragment_id),
                    key=fragment.fragment_id,
                    fragment_id=stored_fragment_id,
                )
            )

            if fragment.run_id is not None:
                index_rollbacks.append(
                    self._append_index(
                        self._run_index_path(fragment.run_id),
                        key=fragment.run_id,
                        fragment_id=stored_fragment_id,
                    )
                )
            if fragment.manifest_id is not None:
                index_rollbacks.append(
                    self._append_index(
                        self._manifest_index_path(fragment.manifest_id),
                        key=fragment.manifest_id,
                        fragment_id=stored_fragment_id,
                    )
                )
            for node in fragment.nodes:
                index_rollbacks.append(
                    self._append_index(
                        self._node_index_path(node.node_id),
                        key=node.node_id,
                        fragment_id=stored_fragment_id,
                    )
                )
        except (OSError, TypeError, ValueError):
            for index_path, checkpoint_offset in reversed(index_rollbacks):
                with suppress(OSError):
                    _truncate_index_to_offset(index_path, offset=checkpoint_offset)
            if existing_fragment_payload is None:
                with suppress(OSError):
                    if fragment_path.exists():
                        fragment_path.unlink()
            else:
                with suppress(OSError):
                    atomic_write_text(fragment_path, existing_fragment_payload)
            raise

    def get(self, fragment_id: str) -> LineageGraphFragment | None:
        """Load one fragment by identifier if present."""
        started_at = perf_counter()
        status = "success"
        try:
            fragment = self._load_fragment(fragment_id)
            if fragment is None:
                stored_fragment_ids = _load_fragment_ids(
                    self._semantic_fragment_index_path(fragment_id),
                    key=fragment_id,
                )
                if not stored_fragment_ids:
                    status = "miss"
                    return None
                if len(stored_fragment_ids) > 1:
                    status = "failed"
                    raise ValueError(
                        "Semantic lineage fragment id resolves to multiple stored "
                        "occurrence records; use run_id or manifest_id lookup for "
                        "historical reconstruction"
                    )
                fragment = self._load_fragment(stored_fragment_ids[0])
                if fragment is None:
                    status = "miss"
                    return None
            return fragment
        except (OSError, TypeError, ValueError):
            status = "failed"
            raise
        finally:
            emit_control_plane_read_metrics(
                self.metrics,
                store="lineage",
                operation="get",
                status=status,
                duration_seconds=perf_counter() - started_at,
            )

    def list_by_run_id(self, run_id: RunID) -> list[LineageGraphFragment]:
        """Return fragments linked to one run identifier."""
        started_at = perf_counter()
        status = "success"
        try:
            fragments = self._load_from_index(
                self._run_index_path(str(run_id)),
                key=str(run_id),
            )
            if not fragments:
                status = "miss"
            return fragments
        except (OSError, TypeError, ValueError):
            status = "failed"
            raise
        finally:
            emit_control_plane_read_metrics(
                self.metrics,
                store="lineage",
                operation="list_by_run_id",
                status=status,
                duration_seconds=perf_counter() - started_at,
            )

    def list_by_manifest_id(self, manifest_id: str) -> list[LineageGraphFragment]:
        """Return fragments linked to one manifest identifier."""
        started_at = perf_counter()
        status = "success"
        try:
            fragments = self._load_from_index(
                self._manifest_index_path(manifest_id),
                key=manifest_id,
            )
            if not fragments:
                status = "miss"
            return fragments
        except (OSError, TypeError, ValueError):
            status = "failed"
            raise
        finally:
            emit_control_plane_read_metrics(
                self.metrics,
                store="lineage",
                operation="list_by_manifest_id",
                status=status,
                duration_seconds=perf_counter() - started_at,
            )

    def list_by_node_id(self, node_id: str) -> list[LineageGraphFragment]:
        """Return fragments that mention one node identifier."""
        started_at = perf_counter()
        status = "success"
        try:
            fragments = self._load_from_index(
                self._node_index_path(node_id),
                key=node_id,
            )
            if not fragments:
                status = "miss"
            return fragments
        except (OSError, TypeError, ValueError):
            status = "failed"
            raise
        finally:
            emit_control_plane_read_metrics(
                self.metrics,
                store="lineage",
                operation="list_by_node_id",
                status=status,
                duration_seconds=perf_counter() - started_at,
            )

    def _fragment_path(self, fragment_id: str) -> Path:
        """Resolve the fragment JSON path for one fragment identifier."""
        return (
            self.base_path / "fragments" / f"{_stable_key_filename(fragment_id)}.json"
        )

    def _run_index_path(self, run_id: str) -> Path:
        """Resolve the run-id index path."""
        return self.base_path / "_by_run_id" / f"{_stable_key_filename(run_id)}.jsonl"

    def _semantic_fragment_index_path(self, fragment_id: str) -> Path:
        """Resolve the semantic-fragment index path."""
        return (
            self.base_path
            / "_by_fragment_id"
            / f"{_stable_key_filename(fragment_id)}.jsonl"
        )

    def _manifest_index_path(self, manifest_id: str) -> Path:
        """Resolve the manifest-id index path."""
        return (
            self.base_path
            / "_by_manifest_id"
            / f"{_stable_key_filename(manifest_id)}.jsonl"
        )

    def _node_index_path(self, node_id: str) -> Path:
        """Resolve the node-id index path."""
        return self.base_path / "_by_node_id" / f"{_stable_key_filename(node_id)}.jsonl"

    def _append_index(
        self, index_path: Path, *, key: str, fragment_id: str
    ) -> tuple[Path, int]:
        """Append one fragment identifier to a JSONL lookup index."""
        checkpoint_offset = _append_jsonl_payload(
            index_path,
            (
                json.dumps(
                    {"key": key, "fragment_id": fragment_id},
                    sort_keys=True,
                )
                + "\n"
            ).encode("utf-8"),
        )
        return index_path, checkpoint_offset

    def _load_from_index(
        self,
        index_path: Path,
        *,
        key: str,
    ) -> list[LineageGraphFragment]:
        """Load fragments referenced by one lookup index."""
        fragments: list[LineageGraphFragment] = []
        for fragment_id in _load_fragment_ids(index_path, key=key):
            fragment = self._load_fragment(fragment_id)
            if fragment is not None:
                fragments.append(fragment)
        return fragments

    def _load_fragment(self, fragment_id: str) -> LineageGraphFragment | None:
        """Load one fragment payload without emitting public lookup metrics."""
        fragment_path = self._fragment_path(fragment_id)
        if not fragment_path.exists():
            return None
        payload = json.loads(fragment_path.read_text(encoding="utf-8"))
        if not isinstance(payload, dict):
            raise ValueError("Lineage fragment payload must be a JSON object")
        fragment = LineageGraphFragment.from_dict(payload)
        stored_fragment_id = fragment.stored_fragment_id
        if stored_fragment_id is not None:
            return fragment if stored_fragment_id == fragment_id else None
        return fragment if fragment.fragment_id == fragment_id else None

def _resolve_ledger_pipeline(entry: RunLedgerEntry) -> str:
    """Resolve the canonical pipeline label from diagnostic entry details."""
    if entry.details is None:
        return "unknown"
    diagnostic = entry.details.get("_diagnostic")
    if not isinstance(diagnostic, dict):
        return "unknown"
    pipeline = diagnostic.get("pipeline")
    if pipeline is None:
        return "unknown"
    text = str(pipeline).strip()
    return text or "unknown"

def _emit_ledger_append_metric(
    metrics: MetricsPort | None,
    *,
    pipeline: str,
    event_type: str,
    status: str,
) -> None:
    """Emit one run-ledger append metric when metrics are enabled."""
    if metrics is None:
        return
    metrics.increment_counter(
        "bioetl_control_plane_ledger_appends_total",
        1,
        {
            "pipeline": pipeline,
            "event_type": event_type,
            "status": status,
        },
    )

def _emit_ledger_append_duration_metric(
    metrics: MetricsPort | None,
    *,
    pipeline: str,
    event_type: str,
    status: str,
    duration_seconds: float,
) -> None:
    """Emit one run-ledger append duration metric when metrics are enabled."""
    if metrics is None:
        return
    metrics.observe_histogram(
        "bioetl_control_plane_ledger_append_duration_seconds",
        duration_seconds,
        {
            "pipeline": pipeline,
            "event_type": event_type,
            "status": status,
        },
    )

def _emit_terminal_event_metric(
    metrics: MetricsPort | None,
    *,
    pipeline: str,
    event_type: str,
) -> None:
    """Mirror persisted terminal outcomes into one crash-safe aggregate family."""
    if metrics is None:
        return
    if event_type == RUN_FINISHED_EVENT:
        terminal_status = "success"
    elif event_type == RUN_FAILED_EVENT:
        terminal_status = "failed"
    elif event_type == RUN_SHUTDOWN_EVENT:
        terminal_status = "shutdown"
    else:
        return
    metrics.increment_counter(
        "bioetl_control_plane_terminal_events_total",
        1,
        {
            "pipeline": pipeline,
            "terminal_status": terminal_status,
        },
    )

def _has_idempotent_duplicate(
    entries: list[RunLedgerEntry],
    *,
    idempotency_key: str | None,
) -> bool:
    """Return whether a logical event has already been persisted."""
    if idempotency_key is None:
        return False
    return any(entry.idempotency_key == idempotency_key for entry in entries)

def _truncate_ledger_to_offset(path: Path, *, offset: int) -> None:
    """Best-effort rollback to one known-good byte offset."""
    if not path.exists():
        return
    file_descriptor = os.open(path, os.O_RDWR)
    try:
        os.ftruncate(file_descriptor, offset)
        os.fsync(file_descriptor)
    finally:
        os.close(file_descriptor)

def _append_jsonl_payload(path: Path, payload: bytes) -> int:
    """Append one full JSONL payload with rollback on partial writes."""
    path.parent.mkdir(parents=True, exist_ok=True)
    file_descriptor = os.open(path, _LEDGER_APPEND_OPEN_FLAGS, 0o666)
    bytes_written = 0
    checkpoint_size = 0
    try:
        checkpoint_size = os.fstat(file_descriptor).st_size
        while bytes_written < len(payload):
            written = os.write(file_descriptor, payload[bytes_written:])
            if written <= 0:
                raise OSError("Ledger append produced an empty write")
            bytes_written += written
        os.fsync(file_descriptor)
        return checkpoint_size
    except OSError:
        if bytes_written > 0:
            try:
                os.ftruncate(file_descriptor, checkpoint_size)
                os.fsync(file_descriptor)
            except OSError:
                pass
        raise
    finally:
        os.close(file_descriptor)

def _ensure_entries_match_manifest_and_run_identity(
    *,
    entries: list[RunLedgerEntry],
    manifest_id: str,
) -> None:
    """Fail closed when one manifest ledger contains mixed identity anchors."""
    if not entries:
        return
    if any(entry.manifest_id != manifest_id for entry in entries):
        raise _RunLedgerCorruptionError(
            f"Run ledger file '{manifest_id}.jsonl' is corrupted: "
            "entries contain a different manifest_id"
        )
    run_ids = {str(entry.run_id) for entry in entries}
    if len(run_ids) > 1:
        raise _RunLedgerCorruptionError(
            f"Run ledger file '{manifest_id}.jsonl' is corrupted: "
            "entries contain multiple run_id values"
        )

def _iter_jsonl_payloads_strict(
    *,
    ledger_path: Path,
    raw_text: str,
) -> list[dict[str, object]]:
    """Parse JSONL objects and fail closed on truncated or invalid content."""
    if not raw_text.strip():
        return []
    if not raw_text.endswith(("\n", "\r")):
        raise _RunLedgerCorruptionError(
            f"Run ledger file '{ledger_path}' is corrupted: truncated tail line"
        )

    payloads: list[dict[str, object]] = []
    for line_number, line in enumerate(raw_text.splitlines(), start=1):
        if not line.strip():
            continue
        try:
            payload = json.loads(line)
        except json.JSONDecodeError as error:
            raise _RunLedgerCorruptionError(
                f"Run ledger file '{ledger_path}' is corrupted at line "
                f"{line_number}: {error.msg}"
            ) from error
        if not isinstance(payload, dict):
            raise _RunLedgerCorruptionError(
                f"Run ledger file '{ledger_path}' is corrupted at line "
                f"{line_number}: payload must be a JSON object"
            )
        payloads.append({str(key): value for key, value in payload.items()})
    return payloads

def _emit_manifest_write_metric(
