        yield Violation(
            category="CONFIGS_CODE",
            path=str(py_file.relative_to(project_root)),
            message="Python-код в configs/ запрещён",
            severity="MUST",
        )

def _check_no_python_in_data(project_root: Path) -> Iterator[Violation]:
