def is_critical_reproducibility_runtime(
    *,
    runtime_environment: object,
    debug_mode: object = False,
) -> bool:
    """Return whether runtime should inherit published strict family defaults."""
    return str(runtime_environment or "").strip().lower() == "prod" or bool(debug_mode)

def _normalized_text(value: object) -> str:
    """Return stripped text for one manifested context value."""
    return str(value or "").strip()

def resolve_reproducibility_family(
    *,
    provider: object,
    entity: object,
    contract_ref: object,
) -> str | None:
    """Resolve the canonical family anchor from manifested provider/entity context."""
    contract_text = _normalized_text(contract_ref)
    if contract_text:
        return contract_text
    family_parts = [
        part for part in (_normalized_text(provider), _normalized_text(entity)) if part
    ]
    if not family_parts:
        return None
    return ".".join(family_parts)

