def registered_reproducibility_families() -> list[str]:
    """Return every registered reproducibility family in the repository."""
    return list(_REGISTERED_SOURCE_FAMILIES + _REGISTERED_COMPOSITE_FAMILIES)

def registered_reproducibility_family_inventory() -> list[dict[str, object]]:
    """Return certification verdicts for every registered pipeline family."""
    inventory: list[dict[str, object]] = []
    for family, execution_context in sorted(
        _REGISTERED_FAMILY_EXECUTION_CONTEXTS.items(),
        key=lambda item: (str(item[1]), str(item[0])),
    ):
        provider, entity = family.split(".", maxsplit=1)
        inventory.append(
            asdict(
                resolve_reproducibility_family_profile(
                    provider=provider,
                    entity=entity,
                    contract_ref=family,
                    execution_context=execution_context,
                )
            )
        )
    return inventory

def published_supported_reproducibility_families() -> list[str]:
    """Return the authoritative strict exact-replay source-family inventory."""
    return list(_PUBLISHED_SUPPORTED_SOURCE_FAMILIES)

def published_production_reproducibility_families() -> list[str]:
    """Return the authoritative production-family inventory."""
    return registered_reproducibility_families()

def published_reproducibility_family_inventory() -> list[dict[str, object]]:
    """Return reproducibility-profile verdicts for every published family."""
    return registered_reproducibility_family_inventory()

def resolve_reproducibility_family_profile(
    *,
    provider: object,
    entity: object,
    contract_ref: object,
    execution_context: ReproducibilityExecutionContext,
) -> ReproducibilityFamilyProfile:
    """Resolve the authoritative reproducibility profile for one run family."""
    family = resolve_reproducibility_family(
        provider=provider,
        entity=entity,
        contract_ref=contract_ref,
    )
    if execution_context == "composite":
        return _build_composite_reproducibility_family_profile(
            family=family,
            execution_context=execution_context,
        )
    return _build_source_reproducibility_family_profile(
        family=family,
        execution_context=execution_context,
    )

"""Shared builders for standard normalization profiles."""

from __future__ import annotations

from collections.abc import Collection, Mapping

from bioetl.domain.normalization.profiles._standard_profile_rule_components import (
    _build_rule_component_context,
    _normalize_special_rules,
    _rule_components,
    _RuleComponentContext,
)
from bioetl.domain.normalization.profiles._standard_profile_spec import (
    StandardProfileSpec,
    coerce_standard_profile_spec,
)
from bioetl.domain.normalization.profiles.base import FieldRule, NormalizationProfile
from bioetl.domain.normalization.profiles.profile_normalizers import (
    normalize_profile_passthrough,
)

__all__ = ["StandardProfileSpec", "build_standard_profile"]

def _normalize_field_collections(
    *collections: Collection[str],
) -> tuple[frozenset[str], ...]:
    """Normalize multiple field collections to frozensets."""
    return tuple(frozenset(collection) for collection in collections)

def _normalize_mapping_fields(
    enum_fields: Mapping[str, frozenset[str]] | None,
    case_fields: Mapping[str, frozenset[str] | None] | None,
) -> tuple[Mapping[str, frozenset[str]], Mapping[str, frozenset[str] | None]]:
    """Normalize mapping fields with default empty dicts."""
    return enum_fields or {}, case_fields or {}

def _build_field_rule(
    *,
    field_name: str,
    meta_fields: frozenset[str],
    set_like_fields: frozenset[str],
    hash_excluded_fields: frozenset[str],
    rule_context: _RuleComponentContext,
) -> FieldRule:
    include_in_hash = (
        field_name not in meta_fields and field_name not in hash_excluded_fields
    )
    if field_name in meta_fields:
        notes = (
            "System/meta field is tracked by the normalization inventory and "
            "excluded from content_hash; persisted-row publication is defined "
            "separately by the Silver/Gold storage contract."
        )
        normalizer = normalize_profile_passthrough
    else:
        normalizer, notes = _rule_components(
            field_name=field_name,
            context=rule_context,
        )
    return FieldRule(
        field_name=field_name,
        normalizer=normalizer,
        include_in_hash=include_in_hash,
        set_like=field_name in set_like_fields,
        notes=notes,
    )

def _normalizer_accepts_record_context(normalizer: FieldNormalizer) -> bool:
    try:
        parameters = tuple(inspect.signature(normalizer).parameters.values())
    except (TypeError, ValueError):
        return False
    return any(
        parameter.name == "record" or parameter.kind == inspect.Parameter.VAR_KEYWORD
        for parameter in parameters
    )

def _normalize_special_rules(
    special_rules: Mapping[str, RuleComponentSpec] | None,
) -> Mapping[str, RuleComponent]:
    """Normalize and coerce special rules."""
    if special_rules is None:
        return {}
    return {
        field_name: _coerce_rule_component(field_name=field_name, component=component)
        for field_name, component in special_rules.items()
    }

def _coerce_rule_component(
    *,
    field_name: str,
    component: RuleComponentSpec,
) -> RuleComponent:
    """Normalize legacy custom-rule shapes to the canonical (normalizer, notes) form."""
    if callable(component):
        return _default_custom_rule_component(
            field_name=field_name, normalizer=component
        )
    if _is_explicit_rule_component(component):
        return cast(RuleComponent, component)
    if _is_single_normalizer_rule_component(component):
        return _default_custom_rule_component(
            field_name=field_name,
            normalizer=component[0],
        )
    raise ValueError(
        "special_rules entries must be a callable or a "
        "(normalizer, notes) tuple; got invalid component "
        f"for field '{field_name}': {component!r}"
    )

def _default_custom_rule_component(
    *,
    field_name: str,
    normalizer: FieldNormalizer,
) -> RuleComponent:
    return (
        normalizer,
        f"Apply custom normalization rule for field '{field_name}'.",
    )

def _is_explicit_rule_component(component: RuleComponentSpec) -> bool:
    return (
        isinstance(component, tuple)
        and len(component) == 2
        and callable(component[0])
        and isinstance(component[1], str)
    )

def _is_single_normalizer_rule_component(component: RuleComponentSpec) -> bool:
    return (
        isinstance(component, tuple) and len(component) == 1 and callable(component[0])
    )

def _handle_special_rules(
    field_name: str, special_rules: Mapping[str, RuleComponent]
) -> RuleComponent | None:
    if field_name in special_rules:
        return special_rules[field_name]
    return None

def _handle_enum_fields(
    field_name: str, enum_fields: Mapping[str, frozenset[str]]
) -> RuleComponent | None:
    if field_name in enum_fields:
        allowed_values = enum_fields[field_name]
        return (
            lambda value: normalize_profile_enum(value, allowed_values=allowed_values),
            (
                f"Normalize enum field '{field_name}' against allowed values, "
                "preserving canonical allowed-value casing and uppercase values "
                "when the registry defines uppercase enums."
            ),
        )
    return None

def _handle_case_fields(
    field_name: str, case_fields: Mapping[str, frozenset[str] | None]
) -> RuleComponent | None:
    if field_name in case_fields:
        allowed_values = case_fields[field_name]
        return (
            lambda value: normalize_profile_case(value, allowed_values=allowed_values),
            f"Normalize case for field '{field_name}'.",
        )
    return None

def _handle_unit_fields(
    field_name: str, unit_fields: frozenset[str]
) -> RuleComponent | None:
    if field_name in unit_fields:
        return (
            normalize_profile_unit,
            f"Canonicalize units for field '{field_name}'.",
        )
    return None

def _handle_null_fields(
    field_name: str, null_fields: frozenset[str]
) -> RuleComponent | None:
    if field_name in null_fields:
        return (
            normalize_profile_null,
            f"Convert pseudo-null values to None for field '{field_name}'.",
        )
    return None

def _compose_null_aware_rule(
    *,
    base_rule: RuleComponent,
    field_name: str,
) -> RuleComponent:
    base_normalizer, base_notes = base_rule

    def _normalize(
        value: object,
        record: Mapping[str, object] | None = None,
    ) -> object:
        null_normalized = normalize_profile_null(value)
        if record is not None and _normalizer_accepts_record_context(base_normalizer):
            return base_normalizer(null_normalized, record=record)
        if null_normalized is None:
            return None
        return base_normalizer(null_normalized)

    _normalize.__name__ = getattr(base_normalizer, "__name__", "_normalize")
    return (
        _normalize,
        f"{base_notes} Pseudo-null values also collapse to None for field '{field_name}'.",
    )

def _handle_field_families(
    field_name: str,
    field_sets: RuleFamilyFieldSets,
) -> RuleComponent | None:
    for fields, normalizer, notes in _rule_family_specs(field_sets=field_sets):
        if field_name in fields:
            return normalizer, notes
    return None

def _rule_components(
    *,
    field_name: str,
    context: _RuleComponentContext,
) -> RuleComponent:
    base_rule = _resolve_base_rule(
        field_name=field_name,
        context=context,
    )
    return _finalize_rule_component(
        field_name=field_name,
        base_rule=base_rule,
        null_fields=context.null_fields,
    )

def _finalize_rule_component(
    *,
    field_name: str,
    base_rule: RuleComponent | None,
    null_fields: frozenset[str],
) -> RuleComponent:
    if field_name not in null_fields:
        return base_rule or _DEFAULT_RULE_COMPONENT
    if base_rule is None:
        null_rule = _handle_null_fields(field_name, null_fields)
        assert null_rule is not None
        return null_rule
    return _compose_null_aware_rule(base_rule=base_rule, field_name=field_name)

