def _resolve_exact_replay_supported_reason(
    *,
    manifest: RunManifest,
    input_snapshots: list[dict[str, object]],
    snapshot_envelope: object,
) -> str | None:
    if manifest.replay_capability != ReplayCapability.EXACT_REPLAY_SUPPORTED:
        return None
    if not bool(getattr(snapshot_envelope, "full_snapshot_envelope", False)):
        return None
    if _has_live_capture_materialized_snapshots(input_snapshots):
        return "materialized_live_capture_snapshot_envelope_present"
    return "full_immutable_input_snapshot_envelope_present"

def _requires_resume_without_snapshot_reason(
    *,
    manifest: RunManifest,
    resume_requested: bool,
) -> bool:
    return (
        manifest.replay_capability == ReplayCapability.RESUME_ONLY or resume_requested
    )

def _has_historical_composite_certified_snapshots(
    input_snapshots: list[dict[str, object]],
) -> bool:
    """Return whether ledger/manifest snapshots carry composite certification."""
    return any(
        _resolve_snapshot_materialization_mode(snapshot)
        == HISTORICAL_COMPOSITE_REPLAY_ENVELOPE_CERTIFIED
        for snapshot in input_snapshots
    )

def _has_historical_source_certified_snapshots(
    input_snapshots: list[dict[str, object]],
) -> bool:
    """Return whether ledger/manifest snapshots carry source certification."""
    return any(
        _resolve_snapshot_materialization_mode(snapshot)
        == HISTORICAL_SOURCE_SNAPSHOT_CERTIFIED
        for snapshot in input_snapshots
    )

def _has_live_capture_materialized_snapshots(
    input_snapshots: list[dict[str, object]],
) -> bool:
    """Return whether ledger/manifest snapshots were materialized post-launch."""
    return any(
        _resolve_snapshot_materialization_mode(snapshot)
        == LIVE_CAPTURE_SNAPSHOT_MATERIALIZED
        for snapshot in input_snapshots
    )

def _is_full_scan_idempotent_rebuild(manifest: RunManifest) -> bool:
    if manifest.launch_context.get("full_scan_idempotent_rebuild", False):
        return True
    candidates = (
        manifest.runtime_config.get("loading_strategy"),
        lookup_mapping_path(manifest.runtime_config, "pipeline", "loading_strategy"),
        manifest.resolved_config.get("loading_strategy"),
        lookup_mapping_path(manifest.resolved_config, "pipeline", "loading_strategy"),
    )
    return any(
        str(candidate or "").strip().lower() == "full_scan_only"
        for candidate in candidates
    )

def _collect_append_mode_semantic_sinks(manifest: RunManifest) -> list[str]:
    normalized = _normalize_declared_append_mode_sinks(
        manifest.launch_context.get("append_mode_semantic_sinks")
    )
    if normalized:
        return normalized
    return sorted(_derive_append_mode_semantic_sinks_from_manifest(manifest))

def _derive_append_mode_semantic_sinks_from_manifest(manifest: RunManifest) -> set[str]:
    """Derive append mode semantic sinks from runtime and resolved configs."""
    derived: set[str] = set()
    for config in (manifest.runtime_config, manifest.resolved_config):
        derived.update(_derive_append_mode_sinks_from_config(config))
    return derived

def _normalize_declared_append_mode_sinks(raw_sinks: object) -> list[str]:
    if not isinstance(raw_sinks, list):
        return []
    return [
        str(sink).strip()
        for sink in raw_sinks
        if isinstance(sink, str) and str(sink).strip()
    ]

def _derive_append_mode_sinks_from_config(config: dict[str, object]) -> set[str]:
    sink_config = lookup_mapping_path(config, "sink")
    if not isinstance(sink_config, dict):
        return set()
    return {
        f"sink.{sink_name}.mode=append"
        for sink_name, sink_settings in sink_config.items()
        if _is_append_enabled_sink(sink_name, sink_settings)
    }

def _is_append_enabled_sink(sink_name: object, sink_settings: object) -> bool:
    if not isinstance(sink_name, str) or not isinstance(sink_settings, dict):
        return False
    mode = str(sink_settings.get("mode") or "").strip().lower()
    enabled = sink_settings.get("enabled")
    return mode == "append" and enabled is not False

def _profile_exact_replay_blockers(profile: object) -> list[str]:
    if getattr(profile, "strict_exact_replay_supported", False):
        return []
    return ["family_outside_supported_exact_replay_boundary"]

def _append_mode_exact_replay_blockers(append_mode_sinks: list[str]) -> list[str]:
    if not append_mode_sinks:
        return []
    return ["append_mode_semantic_outputs"]

def _snapshot_exact_replay_blockers(
    *,
    manifest: RunManifest,
    policy_assessment: ReproducibilityPolicyAssessment,
) -> list[str]:
    snapshot_envelope = policy_assessment.snapshot_envelope
    if not getattr(snapshot_envelope, "any_input_snapshots", False):
        return ["immutable_input_snapshots_missing"]
    if not getattr(snapshot_envelope, "full_snapshot_envelope", False):
        return [
            "partial_input_snapshot_envelope",
            *(
                f"input_snapshot_missing:{source_ref}"
                for source_ref in getattr(
                    snapshot_envelope, "missing_snapshot_source_refs", []
                )
            ),
        ]
    if manifest.replay_capability != ReplayCapability.EXACT_REPLAY_SUPPORTED:
        return ["exact_replay_capability_unavailable"]
    return []

def _dependency_lock_exact_replay_blockers(
    *,
    manifest: RunManifest,
    profile: object,
    policy_assessment: ReproducibilityPolicyAssessment,
) -> list[str]:
    if not _requires_dependency_lock_provenance(
        manifest=manifest,
        profile=profile,
        policy_assessment=policy_assessment,
    ):
        return []
    return ["dependency_lock_provenance_missing"]

def _requires_dependency_lock_provenance(
    *,
    manifest: RunManifest,
    profile: object,
    policy_assessment: ReproducibilityPolicyAssessment,
) -> bool:
    if not getattr(profile, "strict_exact_replay_supported", False):
        return False
    if (
        not getattr(policy_assessment, "strict_requirement_requested", False)
        and manifest.replay_capability != ReplayCapability.EXACT_REPLAY_SUPPORTED
    ):
        return False
    return not manifest.code_provenance.dependency_lock_hash

def _resolve_reproducibility_profile(
    manifest: RunManifest,
) -> ReproducibilityFamilyProfile:
    """Resolve the canonical reproducibility profile for one manifested run."""
    execution_context: Literal["source", "composite"] = (
        "composite" if _is_composite_execution_context(manifest) else "source"
    )
    return resolve_reproducibility_family_profile(
        provider=manifest.provider,
        entity=manifest.entity,
        contract_ref=manifest.code_provenance.contract_ref,
        execution_context=execution_context,
    )

def _resolve_replay_family_contract(manifest: RunManifest) -> dict[str, object]:
    """Return the canonical per-family replay contract for one manifested run."""
    execution_context: Literal["source", "composite"] = (
        "composite" if _is_composite_execution_context(manifest) else "source"
    )
    return build_replay_family_contract(
        provider=manifest.provider,
        entity=manifest.entity,
        contract_ref=manifest.code_provenance.contract_ref,
        execution_context=execution_context,
    )

def _resolve_exact_replay_support_boundary(manifest: RunManifest) -> str:
    """Return the supported exact-replay boundary for one manifested run."""
    return _resolve_reproducibility_profile(manifest).exact_replay_support_boundary

def _build_replay_parentage(manifest: RunManifest) -> dict[str, object]:
    """Return explicit replay ancestry for one manifested run."""
    replay_of_run_id = manifest.replay_of_run_id
    replay_of_manifest_id = manifest.replay_of_manifest_id
    return {
        "is_exact_replay": (
            replay_of_run_id is not None or replay_of_manifest_id is not None
        ),
        "replay_of_run_id": replay_of_run_id,
        "replay_of_manifest_id": replay_of_manifest_id,
    }

def _resolve_required_persistence_profile(manifest: RunManifest) -> str:
    """Resolve the declared minimum persistence profile from manifest context."""
    candidates = (
        manifest.launch_context.get("required_persistence_profile"),
        lookup_mapping_path(
            manifest.runtime_config,
            "pipeline",
            "control_plane",
            "required_persistence_profile",
        ),
        lookup_mapping_path(
            manifest.runtime_config,
            "control_plane",
            "required_persistence_profile",
        ),
        lookup_mapping_path(
            manifest.runtime_config,
            "required_persistence_profile",
        ),
    )
    for candidate in candidates:
        if isinstance(candidate, str):
            normalized = normalize_required_persistence_profile(candidate).lower()
            if normalized in {
                DEFAULT_REQUIRED_PERSISTENCE_PROFILE,
                *STRICT_PERSISTENCE_PROFILES,
            }:
                return normalized
    return DEFAULT_REQUIRED_PERSISTENCE_PROFILE

def _resolve_applied_checkpoint_compatibility_policy(
    *,
    requested_exact_replay: bool,
    requested_policy: str | None,
    required_persistence_profile: str,
) -> str:
    """Resolve the effective checkpoint policy shown in diagnostics."""
    if requested_exact_replay:
        return "hard_fail"
    if required_persistence_profile in STRICT_PERSISTENCE_PROFILES:
        return "hard_fail" if requested_policy != "hard_fail" else requested_policy
    return requested_policy or "observe"

def _resolve_requested_checkpoint_compatibility_policy(
    manifest: RunManifest,
) -> str | None:
    """Resolve requested checkpoint compatibility policy from manifest context."""
    candidates = (
        manifest.launch_context.get("checkpoint_compatibility_policy"),
        lookup_mapping_path(
            manifest.runtime_config,
            "pipeline",
            "control_plane",
            "checkpoint_compatibility_policy",
        ),
        lookup_mapping_path(
            manifest.runtime_config,
            "control_plane",
            "checkpoint_compatibility_policy",
        ),
        lookup_mapping_path(
            manifest.runtime_config,
            "checkpoint_compatibility_policy",
        ),
    )
    for candidate in candidates:
        if isinstance(candidate, str):
            normalized = candidate.strip().lower()
            if normalized in {"observe", "soft_fail", "hard_fail"}:
                return normalized
    return None

def _resolve_replay_mode(
    *,
    manifest: RunManifest,
    requested_exact_replay: bool,
    resume_requested: bool,
) -> str:
    """Resolve operator-facing replay mode from manifest intent and capability."""
    profile = _resolve_reproducibility_profile(manifest)
    if (
        requested_exact_replay
        and manifest.replay_capability == ReplayCapability.EXACT_REPLAY_SUPPORTED
        and profile.strict_exact_replay_supported
    ):
        return "exact_replay"
    if manifest.replay_capability == ReplayCapability.EXACT_REPLAY_SUPPORTED:
        return "same_data_state_recovery"
    if resume_requested or manifest.replay_capability == ReplayCapability.RESUME_ONLY:
        return "resume"
    return "rebuild"

def _resolve_continuation_mode(
    *,
    manifest: RunManifest,
    requested_exact_replay: bool,
    resume_requested: bool,
) -> str:
    """Resolve the bounded continuation/replay/rebuild classification."""
    profile = _resolve_reproducibility_profile(manifest)
    if (
        requested_exact_replay
        and manifest.replay_capability == ReplayCapability.EXACT_REPLAY_SUPPORTED
        and profile.strict_exact_replay_supported
    ):
        return "exact_replay"
    if _is_full_scan_idempotent_rebuild(manifest):
        return "full_scan_idempotent_rebuild"
    if resume_requested or manifest.replay_capability == ReplayCapability.RESUME_ONLY:
        if _is_composite_execution_context(manifest):
            return "checkpoint_snapshot_plus_ledger_suffix_resume"
        return "checkpoint_snapshot_only_resume"
    return "rebuild_only"

def _resolve_replay_capability_reason(
    *,
    manifest: RunManifest,
    input_snapshots: list[dict[str, object]],
    resume_requested: bool,
    policy_assessment: ReproducibilityPolicyAssessment,
) -> str:
    """Return one operator-facing explanation for replay capability."""
    profile = _resolve_reproducibility_profile(manifest)
    snapshot_envelope = policy_assessment.snapshot_envelope
    if not profile.strict_exact_replay_supported:
        return "family_outside_supported_exact_replay_boundary"
    if _collect_append_mode_semantic_sinks(manifest):
        return "append_mode_semantic_outputs_block_exact_replay"
    if _has_partial_input_snapshot_envelope(snapshot_envelope):
        return "partial_input_snapshot_envelope"
    if _has_historical_composite_certified_snapshots(input_snapshots):
        return "certified_historical_composite_snapshot_envelope_present"
    if _has_historical_source_certified_snapshots(input_snapshots):
        return "certified_historical_source_snapshot_envelope_present"
    exact_replay_reason = _resolve_exact_replay_supported_reason(
        manifest=manifest,
        input_snapshots=input_snapshots,
        snapshot_envelope=snapshot_envelope,
    )
    if exact_replay_reason is not None:
        return exact_replay_reason
    if _requires_resume_without_snapshot_reason(
        manifest=manifest,
        resume_requested=resume_requested,
    ):
        return "resume_requested_without_snapshot_backed_inputs"
    if _is_composite_execution_context(manifest):
        return "composite_snapshot_envelope_missing"
    return "immutable_input_snapshots_missing"

def _resolve_replay_occurrence_kind(
    *,
    manifest: RunManifest,
    input_snapshots: list[dict[str, object]],
    policy_assessment: ReproducibilityPolicyAssessment,
) -> str:
    """Return the bounded replay-role classification for one manifested run."""
    replay_parentage = _build_replay_parentage(manifest)
    if bool(replay_parentage["is_exact_replay"]):
        return "exact_replay_child_run"
    if _has_historical_composite_certified_snapshots(input_snapshots):
        if policy_assessment.snapshot_envelope.full_snapshot_envelope:
            return "historical_composite_replay_certified_parent"
        return "historical_composite_certification_incomplete"
    if _has_historical_source_certified_snapshots(input_snapshots):
        if policy_assessment.snapshot_envelope.full_snapshot_envelope:
            return "historical_source_replay_certified_parent"
        return "historical_source_certification_incomplete"
    if _has_live_capture_materialized_snapshots(input_snapshots):
        if policy_assessment.snapshot_envelope.full_snapshot_envelope:
            return "materialized_replayable_parent"
        return "materialized_parent_incomplete"
    if policy_assessment.snapshot_envelope.full_snapshot_envelope:
        return "launch_time_snapshot_backed_run"
    return "ordinary_live_capture"

def _resolve_historical_live_run_upgrade_state(
    *,
    manifest: RunManifest,
    input_snapshots: list[dict[str, object]],
    policy_assessment: ReproducibilityPolicyAssessment,
) -> str:
    """Return the bounded upgrade path for live runs lacking launch-time snapshots."""
    profile = _resolve_reproducibility_profile(manifest)
    replay_parentage = _build_replay_parentage(manifest)
    if _is_composite_execution_context(manifest) or bool(
        replay_parentage["is_exact_replay"]
    ):
        return "not_applicable"
    if _has_historical_source_certified_snapshots(input_snapshots):
        if policy_assessment.snapshot_envelope.full_snapshot_envelope:
            return "historical_source_replay_certified"
        return "historical_source_certification_incomplete"
    if _has_live_capture_materialized_snapshots(input_snapshots):
        if policy_assessment.snapshot_envelope.full_snapshot_envelope:
            return "already_materialized_replayable_parent"
        return "incomplete_materialization_evidence"
    if policy_assessment.snapshot_envelope.full_snapshot_envelope:
        return "not_needed_snapshot_backed_at_launch"
    if not profile.post_capture_replayable_parent_supported:
        return "outside_supported_boundary"
    return "awaiting_input_snapshot_published_evidence"

def _resolve_broader_historical_exact_replay_state(
    *,
    manifest: RunManifest,
    input_snapshots: list[dict[str, object]],
    policy_assessment: ReproducibilityPolicyAssessment,
) -> str:
    """Return the bounded state for the broader certified historical tranche."""
    replay_parentage = _build_replay_parentage(manifest)
    if bool(replay_parentage["is_exact_replay"]):
        return "exact_replay_child_run"
    if _has_historical_composite_certified_snapshots(input_snapshots):
        if policy_assessment.snapshot_envelope.full_snapshot_envelope:
            return "historical_composite_replay_certified"
        return "historical_composite_certification_incomplete"
    if _has_historical_source_certified_snapshots(input_snapshots):
        if policy_assessment.snapshot_envelope.full_snapshot_envelope:
            return "historical_source_replay_certified"
        return "historical_source_certification_incomplete"
    if _has_live_capture_materialized_snapshots(input_snapshots):
        return "within_post_capture_parent_boundary"
    if policy_assessment.snapshot_envelope.full_snapshot_envelope:
        return "within_launch_time_snapshot_boundary"
    if _is_composite_execution_context(manifest):
        return "awaiting_certified_source_lineage"
    return "awaiting_historical_snapshot_certification"

def _build_replay_state_projection(
    *,
    manifest: RunManifest,
    input_snapshots: list[dict[str, object]],
    policy_assessment: ReproducibilityPolicyAssessment,
) -> dict[str, str]:
    """Return canonical replay-state fields shared by base and refreshed views."""
    return {
        "replay_occurrence_kind": _resolve_replay_occurrence_kind(
            manifest=manifest,
            input_snapshots=input_snapshots,
            policy_assessment=policy_assessment,
        ),
        "historical_live_run_upgrade_state": (
            _resolve_historical_live_run_upgrade_state(
                manifest=manifest,
                input_snapshots=input_snapshots,
                policy_assessment=policy_assessment,
            )
        ),
        "broader_historical_exact_replay_state": (
            _resolve_broader_historical_exact_replay_state(
                manifest=manifest,
                input_snapshots=input_snapshots,
                policy_assessment=policy_assessment,
            )
        ),
        "source_posture": _resolve_source_posture(policy_assessment),
    }

"""Nested-config and input-snapshot support helpers for replay diagnostics."""

from __future__ import annotations

from collections.abc import Mapping

from bioetl.application.services.control_plane._historical_replay_certification import (
    LIVE_CAPTURE_SNAPSHOT_MATERIALIZED,
    MIXED_POST_MANIFEST_SNAPSHOT_MATERIALIZATION,
)
from bioetl.application.services.control_plane._run_manifest_snapshot_payloads import (
    manifest_input_snapshot_trace_refs,
)
from bioetl.domain.control_plane import RunLedgerEntry, RunManifest
from bioetl.domain.control_plane.run_ledger import INPUT_SNAPSHOT_PUBLISHED_EVENT
from bioetl.domain.normalization import (
    compute_input_snapshot_identity_fingerprint as compute_snapshot_identity_fingerprint,
)

def lookup_mapping_path(
    mapping: Mapping[str, object],
    *path: str,
) -> object | None:
    """Read one nested mapping path using only mapping-shaped objects."""
    current: object = mapping
    for component in path:
        if not isinstance(current, Mapping):
            return None
        current = current.get(component)
    return current

def collect_input_snapshot_refs(manifest: RunManifest) -> list[dict[str, object]]:
    """Return deterministic flattened snapshot provenance extracted from source refs."""
    return manifest_input_snapshot_trace_refs(manifest)

def collect_input_snapshot_ids(input_snapshots: list[dict[str, object]]) -> list[str]:
    """Return deterministic snapshot identities for resume/exact-replay anchors."""
    return [
        str(snapshot_id)
        for snapshot_id in (snapshot.get("snapshot_id") for snapshot in input_snapshots)
        if snapshot_id is not None
    ]

def collect_input_snapshot_content_hashes(
    input_snapshots: list[dict[str, object]],
) -> list[str]:
    """Return deterministic snapshot content hashes for operator inspection."""
    return [
        str(content_hash)
        for content_hash in (
            snapshot.get("content_hash") for snapshot in input_snapshots
        )
        if content_hash is not None
    ]

def compute_input_snapshot_identity_fingerprint(
    input_snapshots: list[dict[str, object]],
) -> str | None:
    """Compute the same stable replay-anchor fingerprint shape used by checkpoints."""
    return compute_snapshot_identity_fingerprint(list(input_snapshots))

def collect_ledger_input_snapshot_refs(
    ledger_entries: tuple[RunLedgerEntry, ...],
) -> list[dict[str, object]]:
    """Return input snapshots materialized after manifest creation via ledger."""
    refs: dict[str, dict[str, object]] = {}
    for entry in ledger_entries:
        if entry.event_type != INPUT_SNAPSHOT_PUBLISHED_EVENT:
            continue
        details = entry.details if isinstance(entry.details, Mapping) else {}
        snapshot_id = _snapshot_required_text(details.get("snapshot_id"))
        content_hash = _snapshot_required_text(details.get("content_hash"))
        immutable_uri = _snapshot_required_text(details.get("immutable_uri"))
        if snapshot_id is None or content_hash is None or immutable_uri is None:
            continue
        refs[snapshot_id] = {
            "provider": _snapshot_required_text(details.get("provider")),
            "entity": _snapshot_required_text(details.get("entity")),
            "pipeline_name": _snapshot_required_text(details.get("pipeline_name")),
            "query": _snapshot_required_text(details.get("query")),
            "snapshot_id": snapshot_id,
            "content_hash": content_hash,
            "immutable_uri": immutable_uri,
            "query_fingerprint": _snapshot_required_text(
                details.get("query_fingerprint")
            ),
            "storage_provider": _snapshot_required_text(
                details.get("storage_provider")
            ),
            "object_bucket": _snapshot_required_text(details.get("object_bucket")),
            "object_key": _snapshot_required_text(details.get("object_key")),
            "object_version_id": _snapshot_required_text(
                details.get("object_version_id")
            ),
            "etag": _snapshot_required_text(details.get("etag")),
            "last_modified": _snapshot_required_text(details.get("last_modified")),
            "captured_at": _snapshot_required_text(details.get("captured_at")),
            "materialization_mode": _snapshot_required_text(
                details.get("materialization_mode")
            )
            or LIVE_CAPTURE_SNAPSHOT_MATERIALIZED,
            "certification_scope": _snapshot_required_text(
                details.get("certification_scope")
            ),
            "certification_basis": _snapshot_required_text(
                details.get("certification_basis")
            ),
            "certification_artifact_ref": _snapshot_required_text(
                details.get("certification_artifact_ref")
            ),
            "upstream_run_id": _snapshot_required_text(details.get("upstream_run_id")),
            "upstream_manifest_id": _snapshot_required_text(
                details.get("upstream_manifest_id")
            ),
            "source_event_id": entry.entry_id,
        }
    return [refs[key] for key in sorted(refs)]

def resolve_post_manifest_input_snapshot_materialization_mode(
    input_snapshots: list[dict[str, object]],
) -> str | None:
    """Return the deterministic post-manifest materialization mode summary."""
    modes = sorted(
        {
            str(snapshot.get("materialization_mode") or "").strip()
            for snapshot in input_snapshots
            if isinstance(snapshot, Mapping)
            and str(snapshot.get("materialization_mode") or "").strip()
        }
    )
    if not modes:
        return None
    if len(modes) == 1:
        return modes[0]
    return MIXED_POST_MANIFEST_SNAPSHOT_MATERIALIZATION

def merge_ledger_input_snapshots_into_summary(
    summary: dict[str, object],
    ledger_entries: tuple[RunLedgerEntry, ...],
) -> dict[str, object]:
    """Merge ledger-derived input snapshots into diagnostics without mutating manifest."""
    ledger_snapshots = collect_ledger_input_snapshot_refs(ledger_entries)
    if not ledger_snapshots:
        return summary
    merged = dict(summary)
    snapshots_by_id = {
        str(snapshot.get("snapshot_id")): dict(snapshot)
        for snapshot in merged.get("input_snapshots", [])
        if isinstance(snapshot, Mapping) and snapshot.get("snapshot_id") is not None
    }
    for snapshot in ledger_snapshots:
        snapshots_by_id[str(snapshot["snapshot_id"])] = snapshot
    input_snapshots = [snapshots_by_id[key] for key in sorted(snapshots_by_id)]
    merged["input_snapshots"] = input_snapshots
    merged["input_snapshot_count"] = len(input_snapshots)
    merged["input_snapshot_ids"] = collect_input_snapshot_ids(input_snapshots)
    merged["input_snapshot_content_hashes"] = collect_input_snapshot_content_hashes(
        input_snapshots
    )
    merged["input_snapshot_identity_fingerprint"] = (
        compute_input_snapshot_identity_fingerprint(input_snapshots)
    )
    merged["input_snapshot_materialization_mode"] = (
        resolve_post_manifest_input_snapshot_materialization_mode(input_snapshots)
    )
    if merged.get("source_posture") == "live_or_unknown_inputs":
        merged["source_posture"] = str(
            merged.get("input_snapshot_materialization_mode") or "ledger_derived"
        )
    if merged.get("snapshot_status") == "none":
        merged["snapshot_status"] = "ledger_derived"
    return merged

def _snapshot_required_text(value: object) -> str | None:
    if value is None:
        return None
    text = str(value).strip()
    return text or None

"""Source-ref and composite replay helpers for run-manifest diagnostics."""

from __future__ import annotations

from datetime import datetime
from typing import cast

from bioetl.domain.control_plane import (
    RunInputSnapshotRef,
    RunLedgerEntry,
    RunManifest,
    RunSourceRef,
)
from bioetl.domain.control_plane.run_ledger import (
    COMPOSITE_DEPENDENCY_COMPLETED_EVENT,
    COMPOSITE_ENRICHER_COMPLETED_EVENT,
    COMPOSITE_MERGE_COMPLETED_EVENT,
)

__all__ = [
    "_attach_rich_composite_replay_support",
    "_build_effective_source_refs",
]

_RICH_COMPOSITE_REPLAY_EVENTS = frozenset(
    {
        COMPOSITE_DEPENDENCY_COMPLETED_EVENT,
        COMPOSITE_ENRICHER_COMPLETED_EVENT,
        COMPOSITE_MERGE_COMPLETED_EVENT,
    }
)

def _build_effective_source_refs(
    *,
    manifest: RunManifest,
    input_snapshots: list[object],
) -> tuple[RunSourceRef, ...]:
    snapshots_by_source = _group_input_snapshots_by_source(
        manifest=manifest,
        input_snapshots=input_snapshots,
    )
    if not snapshots_by_source:
        return manifest.source_refs
    effective_refs = _merge_manifest_source_refs(
        manifest=manifest,
        snapshots_by_source=snapshots_by_source,
    )
    effective_refs.extend(_build_additional_source_refs(snapshots_by_source))
    return tuple(effective_refs)

def _group_input_snapshots_by_source(
    *,
    manifest: RunManifest,
    input_snapshots: list[object],
) -> dict[tuple[str, str, str, str | None], list[RunInputSnapshotRef]]:
    """Group input snapshots by their effective source identity."""
    snapshots_by_source: dict[
        tuple[str, str, str, str | None],
        list[RunInputSnapshotRef],
    ] = {}
    for item in input_snapshots:
        if not isinstance(item, dict):
            continue
        provider = str(item.get("provider") or manifest.provider).strip()
        entity = str(item.get("entity") or manifest.entity).strip()
        pipeline_name = str(item.get("pipeline_name") or manifest.pipeline_name).strip()
        query_value = item.get("query")
        query = str(query_value).strip() if query_value is not None else None
        snapshots_by_source.setdefault(
            (provider, entity, pipeline_name, query),
            [],
        ).append(_build_snapshot_ref(item))
    return snapshots_by_source

def _pop_matching_source_snapshots(
    *,
    snapshots_by_source: dict[
        tuple[str, str, str, str | None], list[RunInputSnapshotRef]
    ],
    provider: str,
    entity: str,
    pipeline_name: str,
    query: str | None,
) -> list[RunInputSnapshotRef]:
    """Resolve ledger-derived snapshots back onto a manifest-declared source."""
    exact_key = (provider, entity, pipeline_name, query)
    if query is not None:
        return snapshots_by_source.pop(exact_key, [])

    matched_keys = [
        key
        for key in snapshots_by_source
        if key[:3] == (provider, entity, pipeline_name)
    ]
    snapshots: list[RunInputSnapshotRef] = []
    for key in matched_keys:
        snapshots.extend(snapshots_by_source.pop(key, []))
    return snapshots

def _build_additional_source_refs(
    snapshots_by_source: dict[
        tuple[str, str, str, str | None], list[RunInputSnapshotRef]
    ],
) -> list[RunSourceRef]:
    """Build source refs discovered only from input snapshots."""
    return [
        RunSourceRef(
            provider=provider,
            entity=entity,
            pipeline_name=pipeline_name,
            query=query,
            input_snapshots=tuple(snapshots),
        )
        for (provider, entity, pipeline_name, query), snapshots in sorted(
            snapshots_by_source.items()
        )
    ]

def _attach_rich_composite_replay_support(
    summary: dict[str, object],
    ledger_entries: tuple[RunLedgerEntry, ...],
) -> dict[str, object]:
    """Mark composite rich replay support only when ledger evidence is present."""
    observed_events = {
        entry.event_type
        for entry in ledger_entries
        if entry.event_type in _RICH_COMPOSITE_REPLAY_EVENTS
    }
    if not _RICH_COMPOSITE_REPLAY_EVENTS.issubset(observed_events):
        return summary
    updated = dict(summary)
    updated["composite_resume_rich_replay_supported"] = True
    return updated

