"""Pure claim-building helpers for historical replay closure."""

from __future__ import annotations

from typing import Protocol, cast

from bioetl.application.services.control_plane.historical_replay_closure_models import (
    HistoricalReplayResidualDispositionRecord,
)

def _record_manifest_id(record: object) -> str | None:
    if not hasattr(record, "manifest_id"):
        return None
    return cast(_ManifestRecord, record).manifest_id

def build_narrowed_scope_global_claim(
    *,
    unresolved_records: tuple[object, ...],
    narrowed_scope_blockers: tuple[str, ...],
) -> dict[str, object]:
    """Build a retained-certifiable-scope claim gate."""
    claimed = not unresolved_records and not narrowed_scope_blockers
    if claimed:
        reason = (
            "retained_certifiable_historical_scope_has_no_remaining_unresolved_runs"
        )
    elif unresolved_records:
        reason = "residual_historical_runs_lack_explicit_resolution_disposition"
    else:
        reason = "retained_certifiable_scope_still_contains_in_scope_blockers"
    blocked_manifest_ids = [
        *[
            manifest_id
            for record in unresolved_records
            if (manifest_id := _record_manifest_id(record)) is not None
        ],
        *narrowed_scope_blockers,
    ]
    return {
        "claimed": claimed,
        "verdict": "claim_supported" if claimed else "claim_blocked",
        "reason": reason,
        "scope": "retained_certifiable_historical_runs",
        "blocked_manifest_ids": blocked_manifest_ids,
    }

def has_irrecoverable_dispositions(
    disposition_map: dict[str, HistoricalReplayResidualDispositionRecord],
) -> bool:
    """Return whether any residual disposition is explicitly irrecoverable."""
    return any(
        disposition.disposition == "irrecoverable_missing_immutable_evidence"
        for disposition in disposition_map.values()
    )

def universal_scope_claim_block_reason(
    *,
    unresolved_records: tuple[object, ...],
    has_irrecoverable: bool,
    unsupported_count: int,
) -> str:
    """Resolve the deterministic block reason for a universal replay claim."""
    if unresolved_records:
        return "residual_historical_runs_lack_explicit_resolution_disposition"
    if has_irrecoverable:
        return "irrecoverable_legacy_runs_block_universal_historical_claim"
    if unsupported_count:
        return "some_retained_runs_remain_outside_supported_historical_scope"
    return "historical_replay_closure_program_not_yet_completed"

class HistoricalReplayResidualDispositionRecord:
    """Explicit disposition for one residual historical replay blocker."""

    manifest_id: str
    disposition: str
    rationale: str
    evidence_refs: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        if self.disposition not in RESOLUTION_DISPOSITIONS:
            raise ValueError(
                "Unsupported historical replay residual disposition: "
                f"{self.disposition!r}"
            )

    def to_dict(self) -> dict[str, object]:
        return {
            "manifest_id": self.manifest_id,
            "disposition": self.disposition,
            "rationale": self.rationale,
            "evidence_refs": list(self.evidence_refs),
        }

def validate_residual_dispositions(
    *,
    blocked_records: tuple[HistoricalReplayCertifiabilityRecord, ...],
    residual_dispositions: tuple[HistoricalReplayResidualDispositionRecord, ...],
) -> dict[str, HistoricalReplayResidualDispositionRecord]:
    blocked_ids = {record.manifest_id for record in blocked_records}
    disposition_map: dict[str, HistoricalReplayResidualDispositionRecord] = {}
    for disposition in residual_dispositions:
        if disposition.manifest_id not in blocked_ids:
            raise ValueError(
                "Historical replay residual disposition references a manifest "
                f"that is not currently blocked: {disposition.manifest_id!r}"
            )
        if disposition.manifest_id in disposition_map:
            raise ValueError(
                "Duplicate historical replay residual disposition for manifest "
                f"{disposition.manifest_id!r}"
            )
        disposition_map[disposition.manifest_id] = disposition
    return disposition_map

def resolve_closure_verdict(
    *,
    inventory: HistoricalReplayCertifiabilityInventory,
    unresolved_records: tuple[HistoricalReplayCertifiabilityRecord, ...],
    disposition_map: dict[str, HistoricalReplayResidualDispositionRecord],
    claim_scope_mode: HistoricalReplayClaimScopeMode,
) -> tuple[str, str]:
    if (
        inventory.certified_count + inventory.replayable_count == inventory.manifest_count
        and inventory.unsupported_count == 0
    ):
        return (
            "fully_closed",
            "all_retained_historical_runs_are_already_replayable_or_certified",
        )
    if unresolved_records:
        return (
            "residual_disposition_required",
            "blocked_historical_runs_require_explicit_resolution_disposition",
        )
    if (
        claim_scope_mode == "retained_certifiable_historical_runs"
        and narrowed_scope_blockers(disposition_map) == ()
    ):
        return (
            "scope_narrowed_closed",
            "retained_certifiable_historical_scope_is_closed_after_explicit_legacy_scope_narrowing",
        )
    if any(
        disposition.disposition == "irrecoverable_missing_immutable_evidence"
        for disposition in disposition_map.values()
    ):
        return (
            "residual_irrecoverable_subset_present",
            "some_historical_runs_remain_irrecoverable_without_trustworthy_immutable_evidence",
        )
    if inventory.unsupported_count:
        return (
            "outside_supported_scope_present",
            "some_retained_runs_remain_outside_the_current_supported_historical_replay_scope",
        )
    return (
        "residual_resolution_program_in_progress",
        "all_remaining_blocked_runs_have_explicit_resolution_tracks_but_not_yet_closed",
    )

def build_global_claim_gate(
    *,
    inventory: HistoricalReplayCertifiabilityInventory,
    unresolved_records: tuple[HistoricalReplayCertifiabilityRecord, ...],
    disposition_map: dict[str, HistoricalReplayResidualDispositionRecord],
    claim_scope_mode: HistoricalReplayClaimScopeMode,
) -> dict[str, object]:
    blockers = narrowed_scope_blockers(disposition_map)
    if claim_scope_mode == "retained_certifiable_historical_runs":
        return build_narrowed_scope_global_claim(
            unresolved_records=unresolved_records,
            narrowed_scope_blockers=blockers,
        )
    return build_universal_scope_global_claim(
        inventory=inventory,
        unresolved_records=unresolved_records,
        disposition_map=disposition_map,
    )

def narrowed_scope_blockers(
    disposition_map: dict[str, HistoricalReplayResidualDispositionRecord],
) -> tuple[str, ...]:
    excluded_dispositions = {
        "irrecoverable_missing_immutable_evidence",
        "outside_universal_claim_scope",
    }
    return tuple(
        sorted(
            manifest_id
            for manifest_id, disposition in disposition_map.items()
            if disposition.disposition not in excluded_dispositions
        )
    )

def build_retained_corpus_claim(
    *,
    inventory: HistoricalReplayCertifiabilityInventory,
    unresolved_records: tuple[HistoricalReplayCertifiabilityRecord, ...],
) -> dict[str, object]:
    claimed = (
        inventory.remaining_uncertified_count == 0
        and inventory.unsupported_count == 0
        and not unresolved_records
    )
    return {
        "claimed": claimed,
        "verdict": "claim_supported" if claimed else "claim_blocked",
        "reason": (
            "retained_corpus_has_no_remaining_uncertified_or_out_of_scope_runs"
            if claimed
            else "retained_corpus_still_contains_blocked_or_out_of_scope_runs"
        ),
        "scope": "retained_control_plane_corpus",
    }

def build_suggested_resolution(
    record: HistoricalReplayCertifiabilityRecord,
) -> dict[str, object]:
    return {
        "manifest_id": record.manifest_id,
        "run_id": record.run_id,
        "certification_status": record.certification_status,
        "suggested_disposition": _suggested_disposition(record),
        "blocking_reasons": list(record.blocking_reasons),
    }

def _suggested_disposition(
    record: HistoricalReplayCertifiabilityRecord,
) -> str:
    if record.certification_status == "awaiting_source_snapshot_certification":
        return "reconstruct_immutable_evidence"
    if record.certification_status == "awaiting_certified_source_lineage":
        return "certify_upstream_source_lineage"
    if record.certification_status == "outside_certified_historical_scope":
        return "outside_universal_claim_scope"
    return "manual_review_required"

class HistoricalReplayCertifiabilityInventory:
    """Corpus-wide retained-run certifiability inventory."""

    records: tuple[HistoricalReplayCertifiabilityRecord, ...]

    @property
    def manifest_count(self) -> int:
        return len(self.records)

    @property
    def certified_count(self) -> int:
        return sum(
            1
            for record in self.records
            if record.certification_status == "already_certified"
        )

    @property
    def replayable_count(self) -> int:
        return sum(
            1
            for record in self.records
            if record.certification_status == "already_replayable"
        )

    @property
    def awaiting_source_certification_count(self) -> int:
        return sum(
            1
            for record in self.records
            if record.certification_status == "awaiting_source_snapshot_certification"
        )

    @property
    def awaiting_composite_lineage_count(self) -> int:
        return sum(
            1
            for record in self.records
            if record.certification_status == "awaiting_certified_source_lineage"
        )

    @property
    def unsupported_count(self) -> int:
        return sum(
            1
            for record in self.records
            if record.certification_status == "outside_certified_historical_scope"
        )

    @property
    def remaining_uncertified_count(self) -> int:
        return sum(
            1
            for record in self.records
            if record.certification_status
            in {
                "awaiting_source_snapshot_certification",
                "awaiting_certified_source_lineage",
                "needs_operator_review",
            }
        )

    def to_dict(self) -> dict[str, object]:
        """Return one JSON-safe inventory payload."""
        return {
            "manifest_count": self.manifest_count,
            "certified_count": self.certified_count,
            "replayable_count": self.replayable_count,
            "awaiting_source_certification_count": (
                self.awaiting_source_certification_count
            ),
            "awaiting_composite_lineage_count": self.awaiting_composite_lineage_count,
            "unsupported_count": self.unsupported_count,
            "remaining_uncertified_count": self.remaining_uncertified_count,
            "records": [record.to_dict() for record in self.records],
        }

class HistoricalReplayBulkCertificationResult:
    """Result of one deterministic retained-corpus certification pass."""

    inventory_before: HistoricalReplayCertifiabilityInventory
    inventory_after: HistoricalReplayCertifiabilityInventory
    records: tuple[HistoricalReplayBulkCertificationRecord, ...]

    @property
    def completed_count(self) -> int:
        return sum(1 for record in self.records if record.status == "certified")

    @property
    def skipped_count(self) -> int:
        return len(self.records) - self.completed_count

    def to_dict(self) -> dict[str, object]:
        """Return one JSON-safe bulk-certification payload."""
        return {
            "completed_count": self.completed_count,
            "skipped_count": self.skipped_count,
            "inventory_before": self.inventory_before.to_dict(),
            "inventory_after": self.inventory_after.to_dict(),
            "records": [record.to_dict() for record in self.records],
        }

"""Pure policy helpers for retained historical replay corpus workflows."""

from __future__ import annotations

from bioetl.domain.control_plane import RunManifest

CERTIFIED_REPLAY_KINDS = frozenset(
    {
        "historical_source_replay_certified_parent",
        "historical_composite_replay_certified_parent",
    }
)
ALREADY_REPLAYABLE_STATES = frozenset(
    {
        "exact_replay_child_run",
        "within_launch_time_snapshot_boundary",
        "within_post_capture_parent_boundary",
    }
)
ALREADY_CERTIFIED_STATES = frozenset(
    {
        "historical_source_replay_certified",
        "historical_composite_replay_certified",
    }
)
SUPPORTED_BROADER_POLICY = "certified_historical_exact_replay_tranche_supported"

def classify_certification_status(
    *,
    broader_policy: str,
    replay_occurrence_kind: str,
    broader_state: str,
) -> tuple[str, tuple[str, ...]]:
    """Classify one manifest against the supported historical replay tranche."""
    if broader_policy != SUPPORTED_BROADER_POLICY:
        return (
            "outside_certified_historical_scope",
            ("broader_historical_exact_replay_not_supported",),
        )
    if replay_occurrence_kind in CERTIFIED_REPLAY_KINDS or (
        broader_state in ALREADY_CERTIFIED_STATES
    ):
        return ("already_certified", ())
    if broader_state in ALREADY_REPLAYABLE_STATES:
        return ("already_replayable", ())
    if broader_state == "awaiting_historical_snapshot_certification":
        return (
            "awaiting_source_snapshot_certification",
            ("retained_snapshot_certification_required",),
        )
    if broader_state == "awaiting_certified_source_lineage":
        return (
            "awaiting_certified_source_lineage",
            ("certified_source_lineage_required",),
        )
    return (
        "needs_operator_review",
        ("replay_certifiability_state_requires_review",),
    )

def resolve_execution_context(manifest: RunManifest) -> str:
    """Resolve deterministic execution context from manifest fields."""
    context = str(manifest.launch_context.get("execution_context") or "").strip()
    if context:
        return context
    if manifest.provider == "composite":
        return "composite"
    return "source"

def certification_scope_for_context(execution_context: str) -> str | None:
    """Resolve certification scope for a manifest execution context."""
    if execution_context == "composite":
        return "historical_composite_replay"
    if execution_context:
        return "historical_source_replay"
    return None

def bulk_spec_order_key(manifest: RunManifest) -> tuple[int, object, str]:
    """Order source manifests before composite while keeping creation order stable."""
    execution_context = resolve_execution_context(manifest)
    source_first = 0 if execution_context != "composite" else 1
    return (source_first, manifest.created_at, manifest.manifest_id)

